Object.assign(window.TEM8_DICTIONARY, {"flaunt":{"media":{"uk":"media/uk/flaunt__gb_1.mp3","us":"media/us/flaunt__us_1.mp3"},"oxford":{"phon":"flɔːnt","pos":"verb","senses":[{"en":"to show something you are proud of to other people, in order to impress them","cn":"炫耀；夸示；夸耀；卖弄","ex":{"en":"He did not believe in flaunting his wealth.","cn":"他不赞成摆阔。"}},{"en":"to behave in a confident and sexual way to attract attention","cn":"（性感地）招摇过市"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"炫耀;夸耀;卖弄","en":"If you say that someone flaunts their possessions, abilities, or qualities, you mean that they display them in a very obvious way, especially in order to try to obtain other people's admiration.","ex":{"en":"They drove around in Rolls-Royces, openly flaunting their wealth","cn":"他们开着劳斯莱斯到处转悠，公开炫耀他们的财富。"}},{"pos":"VERB 动词","cn":"招摇过市;卖弄性感;搔首弄姿","en":"If you say that someone is flaunting themselves, you disapprove of them because they are behaving in a very confident way, or in a way that is intended to attract sexual attention.","ex":{"en":"She's asking for trouble, flaunting herself like that. Did you see the way Major Winston was looking at her?","cn":"她那么招摇，真是在自找麻烦。看到温斯顿少校看她的样子了吗？"}}]},"examples":[{"en":"She openly flaunted her affair with the senator.","cn":"她公开夸耀与参议员的恋情。"},{"en":"He did not believe in flaunting his wealth.","cn":"他不相信摆阔有什么好处。"}]},"flies":{"media":{"uk":"media/uk/flies__gb_1.mp3","us":"media/us/flies__us_1.mp3"},"oxford":{"phon":"flaɪz","pos":"noun","senses":[{"en":"an opening down the front of a pair of trousers that fastens with a zip or buttons and is usually covered over by a narrow piece of material","cn":"（裤子的）前裆开口","lab":"British English"},{"en":"the space above the stage in a theatre, used for lights and for storing scenery","cn":"（舞台上方）悬吊布景的空间，吊景区"}]},"base":"fly"},"flower":{"media":{"img":["media/pic/flowerlabels_flowers_comp.jpg","media/thumb/flower.jpg"],"uk":"media/uk/flower__gb_1.mp3","us":"media/us/flower__us_1.mp3"},"oxford":{"phon":"ˈflaʊə(r)","pos":"noun","senses":[{"en":"the coloured part of a plant from which the seed or fruit develops. Flowers usually grow at the end of a stem and last only a short time.","cn":"花；花朵","ex":{"en":"The plant has a beautiful bright red flower.","cn":"这株植物开了一朵美丽鲜红的花。"}},{"en":"a plant grown or valued for the beauty of its flowers","cn":"开花植物；花卉","ex":{"en":"a garden full of flowers","cn":"种满花的花园"}},{"en":"a flower with its stem that has been picked as a decoration","cn":"（已摘）带梗的花","ex":{"en":"I picked some flowers.","cn":"我摘了一些花。"}},{"en":"to produce flowers","cn":"开花","g":"[intransitive]","ex":{"en":"This particular variety flowers in July.","cn":"这个品种七月开花。"},"pos":"verb"},{"en":"to develop and become successful","cn":"成熟；繁荣；兴旺","g":"[intransitive]","lab":"literary","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"花朵;鲜花","en":"A flower is the part of a plant which is often brightly coloured, grows at the end of a stem, and only survives for a short time.","ex":{"en":"Each individual flower is tiny.","cn":"每一朵花都很小。"}},{"pos":"N-COUNT 可数名词","cn":"(已摘的)带梗的花","en":"A flower is a stem of a plant that has one or more flowers on it and has been picked, usually with others, for example to give as a present or to put in a vase.","ex":{"en":"...a bunch of flowers sent by a new admirer.","cn":"又一个仰慕者送来的一束鲜花"}},{"pos":"N-COUNT 可数名词","cn":"花卉;开花植物","en":"Flowers are small plants that are grown for their flowers as opposed to trees, shrubs, and vegetables.","ex":{"en":"...a lawned area surrounded by plants and flowers","cn":"周围种着植物和花卉的草地"}},{"pos":"VERB 动词","cn":"开花;盛开","en":"When a plant or tree flowers, its flowers appear and open.","ex":{"en":"Several of these rhododendrons will flower this year for the first time.","cn":"这些杜鹃花有些将在今年首度开花。"}},{"pos":"VERB 动词","cn":"繁荣;成熟;发展","en":"When something flowers, for example a political movement or a relationship, it gets stronger and more successful.","ex":{"en":"Their relationship flowered.","cn":"他们的关系最终开花结果了。"}},{"pos":"N-SING 单数名词","cn":"精华;精英;最好的部分","en":"A person or thing that is described as the flower of something is the best part or example of it.","ex":{"en":"Those killed have been described as the flower of Polish manhood.","cn":"那些牺牲者被称为波兰男子中的精英。"}},{"pos":"PHRASE 短语","cn":"开花;花朵绽放","en":"When a plant is in flower or when it has come into flower, its flowers have appeared and opened.","ex":{"en":"Some of the daffodils are still in flower","cn":"有些水仙花仍在开放。"}}]},"examples":[{"en":"The plant has a beautiful bright red flower.","cn":"这株植物开了一朵美丽鲜红的花。"},{"en":"The roses are in flower early this year.","cn":"今年玫瑰花开得早。"}]},"flowering":{"media":{"uk":"media/uk/flowering__gb_1.mp3","us":"media/us/flowering__us_1.mp3"},"oxford":{"phon":"ˈflaʊərɪŋ","pos":"noun","senses":[{"en":"the time when a plant has flowers","cn":"开花时节","g":"[uncountable]","ex":{"en":"Plant bulbs in September for spring flowering.","cn":"九月种植球茎，春季开花。"}},{"en":"the time when something, especially a period of new ideas in art, music, science, etc., reaches its most complete and successful stage of development","cn":"（艺术、音乐、科学等新思潮的）繁荣时期，鼎盛时期","g":"[countable, usually singular]","ex":{"en":"the flowering of Viennese intellectual life","cn":"维也纳学术生活的繁荣兴盛。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(想法或艺术风格)成熟，风行，盛行","en":"The flowering of something such as an idea or artistic style is the development of its popularity and success.","ex":{"en":"He may be happy with the flowering of new thinking, but he has yet to contribute much to it himself.","cn":"他也许会对新思想的盛行感到高兴，但他本人并没有为此作出多大贡献。"}},{"pos":"ADJ 形容词","cn":"开花的;有花的","en":"Flowering shrubs, trees, or plants are those which produce noticeable flowers."}]},"examples":[{"en":"The 19th century saw a flowering of science and technology. 19","cn":"世纪见证了科学和技术的繁荣。"}],"base":"flower"},"fly":{"media":{"uk":"media/uk/fly__gb_1.mp3","us":"media/us/fly__us_1.mp3"},"oxford":{"phon":"flaɪ","pos":"verb","senses":[{"en":"to move through the air, using wings","cn":"飞；飞翔","g":"[intransitive]","sc":"of bird/insect","ex":{"en":"Penguins can't fly.","cn":"企鹅不会飞。"}},{"en":"to move through air or space","cn":"（在空中或宇宙）飞行，航行","g":"[intransitive]","sc":"aircraft/spacecraft","ex":{"en":"They were on a plane flying from London to New York.","cn":"他们在从伦敦飞往纽约的飞机上。"}},{"en":"to travel in an aircraft or a spacecraft","cn":"（乘航空器或航天器）航行，飞行","g":"[intransitive]","sc":"aircraft/spacecraft","ex":{"en":"Is this the first time that you've flown?","cn":"这是你第一次乘飞机吗？"}},{"en":"to control an aircraft, etc. in the air","cn":"驾驶（飞机等）；操纵（飞行器等）","g":"[transitive, intransitive]","sc":"aircraft/spacecraft","ex":{"en":"He's learning to fly.","cn":"他在学习驾驶飞机。"}},{"en":"to transport goods or passengers in a plane","cn":"空运（货物或乘客）","g":"[transitive]","sc":"aircraft/spacecraft","ex":{"en":"The stranded tourists were finally flown home.","cn":"滞留的游客终于由飞机送返家园。"}},{"en":"to move through the air for a particular distance; to travel over an ocean or area of land in an aircraft","cn":"飞越；（乘飞行器）飞过","g":"[transitive]","sc":"aircraft/spacecraft","ex":{"en":"Some birds fly huge distances when they migrate.","cn":"有些鸟迁徙时飞越很远的距离。"}},{"en":"to go or move quickly","cn":"疾驰；疾行；快速移动","g":"[intransitive]","sc":"move quickly/suddenly","ex":{"en":"The train was flying along.","cn":"火车飞驰着。"}},{"en":"to move suddenly and with force","cn":"猛然移动","g":"[intransitive]","sc":"move quickly/suddenly","ex":{"en":"A large stone came flying in through the window.","cn":"一块大石头飞进了窗户。"}},{"en":"to seem to pass very quickly","cn":"飞逝","g":"[intransitive]","sc":"of time","ex":{"en":"Doesn't time fly?","cn":"时间过得真快！"}},{"en":"if a flag flies, or if you fly it, it is displayed, for example on a pole (= a long piece of wood or metal)","cn":"（旗）飘扬；升，悬挂（旗）","g":"[intransitive, transitive]","sc":"flag","ex":{"en":"Flags were flying at half mast on all public buildings.","cn":"所有的公共建筑都降半旗。"}},{"en":"to move around freely","cn":"自由移动","g":"[intransitive]","sc":"move freely","ex":{"en":"hair flying in the wind","cn":"随风飘拂的头发"}},{"en":"to be talked about by many people","cn":"流传；四处传播","g":"[intransitive]","sc":"of stories/rumours"},{"en":"to escape from somebody/something","cn":"逃避；（从…）逃脱","g":"[transitive, intransitive]","lab":"formal","sc":"escape","ex":{"en":"Both suspects have flown the country.","cn":"两个嫌疑犯都逃到国外了。"}},{"en":"to be successful","cn":"成功","g":"[intransitive]","lab":"especially North American English","sc":"of plan","ex":{"en":"It remains to be seen whether his project will fly.","cn":"他的计划能否成功尚需拭目以待。"}},{"en":"to hit a ball high into the air","cn":"将（球）击出飞球","g":"[intransitive, transitive]","sc":"in baseball"},{"en":"a small flying insect with two wings. There are many different types of fly and many of them spread disease.","cn":"蝇；苍蝇","g":"[countable]","sc":"insect","ex":{"en":"A fly was buzzing against the window.","cn":"一只苍蝇嗡嗡地飞着，直撞窗子。"},"pos":"noun"},{"en":"a fly or something made to look like a fly, that is put on the end of a fishing line and used as bait to catch fish","cn":"（作钓饵的）苍蝇，假蝇","g":"[countable]","sc":"in fishing","ex":{"en":"fly fishing","cn":"用假蝇作饵钓鱼"},"pos":"noun"},{"en":"an opening down the front of a pair of trousers that fastens with a zip or buttons and is usually covered over by a narrow piece of material","cn":"（裤子的）前裆开口","g":"[singular]","lab":"British English also","sc":"on trousers/pants","ex":{"en":"Your fly is undone!","cn":"你的裤子前裆没拉上！"},"pos":"noun"},{"en":"a piece of material that covers the entrance to a tent","cn":"门帘","g":"[countable]","sc":"on tent","pos":"noun"},{"en":"a ball that is hit high into the air","cn":"高飞球；腾空球","sc":"in baseball","pos":"noun"},{"en":"clever and showing good judgement about people, especially so that you can get an advantage for yourself","cn":"机灵的；机警的；不会上当的","lab":"British English","pos":"adjective"},{"en":"fashionable and attractive","cn":"时髦迷人的；漂亮的","lab":"North American English, informal，，","pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"苍蝇","en":"A fly is a small insect with two wings. There are many kinds of flies, and the most common are black in colour."},{"pos":"VERB 动词","cn":"飞;飞行;飞翔","en":"When something such as a bird, insect, or aircraft flies, it moves through the air.","ex":{"en":"The planes flew through the clouds","cn":"飞机穿越云层。"}},{"pos":"VERB 动词","cn":"(乘飞机)飞行，航行","en":"If you fly somewhere, you travel there in an aircraft.","ex":{"en":"He flew to Los Angeles","cn":"他飞往洛杉矶。"}},{"pos":"VERB 动词","cn":"驾驶(飞机)","en":"When someone flies an aircraft, they control its movement in the air.","ex":{"en":"Parker had successfully flown both aircraft","cn":"两架飞机帕克均成功驾驶过。"}},{"pos":"VERB 动词","cn":"空运(乘客或货物)","en":"To fly someone or something somewhere means to take or send them there in an aircraft.","ex":{"en":"It may be possible to fly the women and children out on Thursday","cn":"周四可能会将妇女和儿童空运出去。"}},{"pos":"VERB 动词","cn":"飞舞;飘荡","en":"If something such as your hair is flying about, it is moving about freely and loosely in the air.","ex":{"en":"His long, uncovered hair flew back in the wind","cn":"他那露在外面的长发随风向后飞舞。"}},{"pos":"V-ERG 及物/不及物动词","cn":"升(旗);(旗帜)飘扬","en":"If you fly a flag or if it is flying, you display it at the top of a pole.","ex":{"en":"They flew the flag of the African National Congress","cn":"他们升起非洲人国民大会的旗帜。"}},{"pos":"VERB 动词","cn":"疾驰;飞跑","en":"If you say that someone or something flies in a particular direction, you are emphasizing that they move there with a lot of speed or force.","ex":{"en":"She flew to their bedsides when they were ill","cn":"在他们生病的时候她飞奔至他们身边。"}},{"pos":"VERB 动词","cn":"匆忙离开;赶紧走","en":"If you tell someone that you must fly, you are indicating that you have to leave in a great hurry.","ex":{"en":"I must fly or I'll miss my plane","cn":"我必须赶快走了否则就会误机。"}},{"pos":"VERB 动词","cn":"(故事、谣言等)传开，传播","en":"If stories or rumours are flying around a place, they are being discussed a great deal and by a lot of people within a short period of time.","ex":{"en":"Rumours had been flying around the workrooms all morning","cn":"整个早上流言在各工作间传来传去。"}},{"pos":"N-COUNT 可数名词","cn":"(裤子的)前裆开口","en":"The front opening on a pair of trousers is referred to as the fly, or in British English the flies. It usually consists of a zip or row of buttons behind a band of cloth."},{"pos":"N-COUNT 可数名词","cn":"(作钓饵的)假蝇","en":"In fishing, a fly is a model of a small winged insect that is used as a bait."},{"pos":"PHRASE 短语","cn":"心地善良;心肠软","en":"If you say that someone wouldn't hurt a fly or wouldn't harm a fly, you are emphasizing that they are very kind and gentle.","ex":{"en":"Ray wouldn't hurt a fly.","cn":"雷心肠很软。"}},{"pos":"PHRASE 短语","cn":"攻击;侮辱","en":"If you let fly, you attack someone, either physically by hitting them, or with words by insulting them.","ex":{"en":"A simmering row ended with her letting fly with a stream of obscenities.","cn":"激烈的争吵最后以她一连串的污言秽语而告结束。"}},{"pos":"PHRASE 短语","cn":"匆忙地;赶紧地","en":"If you do something on the fly, you do it quickly without thinking about it or planning it in advance, especially while something else is happening.","ex":{"en":"It was all pretty much done on the fly.","cn":"那几乎都是匆忙之中完成的。"}},{"pos":"PHRASE 短语","cn":"(把…)打翻在地;(使)重重地摔在地上","en":"If you send someone or something flying or if they go flying, they move through the air and fall down with a lot of force.","ex":{"en":"The blow sent the young man flying.","cn":"这一拳把那个年轻人打翻在地。"}},{"pos":"PHRASE 短语","cn":"不为人察觉的观察者","en":"If you say that you would like to be a fly on the wall in a situation that does not involve you, you mean that you would like to see or hear what happens in that situation.","ex":{"en":"What I'd give to be a fly on the wall when Davis finds out what's happened to his precious cargo.","cn":"我多么希望能够看到戴维斯发现他珍贵的货物出事时的样子啊。"}},{"pos":"","cn":"","en":"to fly the coop→see: ;"},{"pos":"","cn":"","en":"as the crow flies→see: ;"},{"pos":"","cn":"","en":". to fly in the face of→see: ;"},{"pos":"","cn":"","en":". to fly the flag→see: ;"},{"pos":"","cn":"","en":". to fly off the handle→see: ;"},{"pos":"","cn":"","en":". a fly in the ointment→see: ;"},{"pos":"","cn":"","en":"pigs might fly→see: ;"},{"pos":"","cn":"","en":"sparks fly→see: ;"},{"pos":"","cn":"","en":"time flies→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"攻击;侮辱","en":"If you fly at someone, you attack them, either physically by hitting them, or with words by insulting them.","ex":{"en":"She flew at him for making a very anti-British remark.","cn":"她攻击他激烈的反英言论。"}},{"pos":"PHRASAL VERB 短语动词","cn":"突然爆发(坏脾气);突然陷入(恐慌)","en":"If you fly into a bad temper or a panic, you suddenly become very angry or anxious and show this in your behaviour.","ex":{"en":"Losing a game would cause him to fly into a rage.","cn":"输掉一场比赛会让他暴跳如雷。"}},{"pos":"","cn":"","en":"相关词组：fly at fly into"}]},"examples":[{"en":"Lufthansa fly to La Paz from Frankfurt.","cn":"汉莎航空公司的飞机从法兰克福飞往拉巴斯。"},{"en":"I'd love to be a fly on the wall when he tells her the news.","cn":"他把这消息告诉她时，我想悄悄在旁观看。"}]},"flux":{"media":{"uk":"media/uk/flux__gb_1.mp3","us":"media/us/flux__us_1.mp3"},"oxford":{"phon":"flʌks","pos":"noun","senses":[{"en":"continuous movement and change","cn":"不断的变动；不停的变化","g":"[uncountable]","ex":{"en":"Our society is in a state of flux.","cn":"我们的社会在不断演变。"}},{"en":"a flow; an act of flowing","cn":"通量；流","g":"[countable, usually singular, uncountable]","lab":"specialist","ex":{"en":"a flux of neutrons","cn":"一个中子流"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"变动;波动","en":"If something is in a state of flux, it is constantly changing.","ex":{"en":"Education remains in a state of flux which will take some time to settle down.","cn":"教育还处于不断变化中，需要一段时间才能稳定下来。"}},{"pos":"N-VAR 可变名词","cn":"流体","en":"You can refer to a flowing mass as a flux .","ex":{"en":"...the flux of cosmic rays.","cn":"宇宙射线流"}}]},"examples":[{"en":"Our society is in a state of flux.","cn":"我们的社会在不断演变。"},{"en":"a flux of neutrons","cn":"一个中子通量"}]},"floating":{"media":{"uk":"media/uk/floating__gb_1.mp3","us":"media/us/floating__us_1.mp3"},"oxford":{"phon":"ˈfləʊtɪŋ","pos":"adjective","senses":[{"en":"not fixed permanently in one particular position or place","cn":"不固定的；流动的；浮动的","lab":"medical","ex":{"en":"floating exchange rates","cn":"浮动汇率"}}]},"examples":[{"en":"a floating population (= one in which people frequently move from one place to another)","cn":"流动人口"},{"en":"( medical","cn":"医 ) a floating kidney 游走肾"}],"base":"float"},"flute":{"media":{"img":["media/pic/woodwind_musicalinstruments_comp.jpg","media/thumb/flute.jpg"],"uk":"media/uk/flute__gb_1.mp3","us":"media/us/flute__us_1.mp3"},"oxford":{"phon":"fluːt","pos":"noun","senses":[{"en":"a musical instrument of the woodwind group, like a thin pipe in shape. The player holds it to the side of his or her face and blows across a hole at one end.","cn":"长笛","ex":{"en":"to play the flute","cn":"吹长笛"}},{"en":"a tall narrow glass used for drinking champagne","cn":"细长香槟杯（形似长笛）"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"长笛","en":"A flute is a musical instrument of the woodwind family. You play it by blowing over a hole near one end while holding it sideways to your mouth."}]}},"flows":{"lemma":"flow","media":{"uk":"media/uk/flow__gb_1.mp3","us":"media/us/flow__us_1.mp3"}},"flag":{"oxford":{"phon":"flæɡ","pos":"noun","senses":[{"en":"a piece of cloth with a special coloured design on it that may be the symbol of a particular country or organization, may be used to give a signal or may have a particular meaning. A flag can be attached to a pole (= a long thin straight piece of wood or metal) or held in the hand.","cn":"旗；旗帜","ex":{"en":"the Italian flag","cn":"意大利国旗"}},{"en":"used to refer to a particular country or organization and its beliefs and values","cn":"旗帜（指某国家或组织及其信仰和价值观）","ex":{"en":"to swear allegiance to the flag","cn":"面对旗帜作效忠宣誓"}},{"en":"a flower that is a type of iris and that grows near water","cn":"菖蒲；鸢尾；香蒲","ex":{"en":"yellow flags","cn":"黄菖蒲"}},{"en":"a large flat square piece of stone that is used for floors, paths, etc.","cn":"石板（方形，用于铺地面、小径等）"},{"en":"to draw attention to information that you think is important, especially by putting a special mark next to it","cn":"标示（重要处）","g":"[transitive]","ex":{"en":"I've flagged the paragraphs that we need to look at in more detail.","cn":"我已用特殊记号标出我们需要更仔细研究的段落。"},"pos":"verb"},{"en":"to become tired, weaker or less enthusiastic","cn":"疲乏；变弱；热情衰减","g":"[intransitive]","ex":{"en":"It had been a long day and the children were beginning to flag.","cn":"这一天真漫长，孩子们都累得打起蔫来。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旗;旗帜;(尤指)国旗","en":"A flag is a piece of cloth which can be attached to a pole and which is used as a sign, signal, or symbol of something, especially of a particular country.","ex":{"en":"The Marines climbed to the roof of the embassy building to raise the American flag","cn":"海军陆战队队员爬到使馆大楼顶上，升起了美国国旗。"}},{"pos":"N-COUNT 可数名词","cn":"(在售旗募捐日出售或在某个位置上作标记用的)小旗，旗状物","en":"A flag is a small piece of paper or cloth attached to a stick or pin which is sold on a flag day or used to mark a particular spot."},{"pos":"N-COUNT 可数名词","cn":"旗帜(新闻用语，代指某个国家、组织或其价值观、权力)","en":"Journalists sometimes refer to the flag of a particular country or organization as a way of referring to the country or organization itself and its values or power.","ex":{"en":"Joining John Whitaker will be his brother Michael also riding under the British flag","cn":"约翰·惠特克将与他的兄弟迈克尔一起代表英国参加这场自行车赛。"}},{"pos":"VERB 动词","cn":"松劲;泄气;疲乏","en":"If you flag or if your spirits flag, you begin to lose enthusiasm or energy.","ex":{"en":"His enthusiasm was in no way flagging","cn":"他的热情丝毫未减。"}},{"pos":"N-COUNT 可数名词","cn":"同 flagstone","en":"A flag is the same as a flagstone ."},{"pos":"PHRASE 短语","cn":"(在国外时)表示并号召拥护自己的国家;（为少数人支持的事业)摇旗呐喊","en":"If you fly the flag, you show that you are proud of your country, or that you support a particular cause, especially when you are in a foreign country or when few other people do.","ex":{"en":"Steve Crabb can fly the flag with distinction for Britain in Barcelona.","cn":"史蒂夫·克拉布在巴塞罗那可以旗帜鲜明地支持英国。"}},{"pos":"PHRASAL VERB 短语动词","cn":"挥手拦下，招手叫(尤指出租车)","en":"If you flag down a vehicle, especially a taxi, you wave at it as a signal for the driver to stop.","ex":{"en":"Marlette was already out of the door, flagging down a taxi.","cn":"马利特已经出门了，正挥手招呼一辆出租车。"}},{"pos":"","cn":"","en":"相关词组：flag down"}]},"media":{"uk":"media/uk/flag__gb_1.mp3","us":"media/us/flag__us_1.mp3","img":["media/ldoce/img/flag.jpg"]},"examples":[{"en":"Our exporters keep the flag flying at international trade exhibitions.","cn":"我们的出口商在国际贸易展览会上代表我们的国家参展。"},{"en":"The report flagged up the dangers of under-age drinking.","cn":"这篇报道引起大众对未成年人饮酒危害的关注。"}]},"flying":{"media":{"uk":"media/uk/flying__gb_1.mp3","us":"media/us/flying__us_1.mp3"},"oxford":{"phon":"ˈflaɪɪŋ","pos":"adjective","senses":[{"en":"able to fly","cn":"能飞的","ex":{"en":"flying insects","cn":"能飞的昆虫"}},{"en":"moving rapidly through the air","cn":"飞溅的；飞射的","ex":{"en":"One passenger was cut by flying glass.","cn":"一乘客被飞来的玻璃划伤。"}},{"en":"travelling in an aircraft","cn":"乘飞机","ex":{"en":"I'm terrified of flying.","cn":"我十分害怕坐飞机。"},"pos":"noun"},{"en":"operating the controls of an aircraft","cn":"飞行；飞行器驾驶","ex":{"en":"flying lessons","cn":"飞行驾驶课"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(动物)会飞的，有翼的","en":"A flying animal has wings and is able to fly.","ex":{"en":"...species of flying insects.","cn":"飞行昆虫的种类"}},{"pos":"PHRASE 短语","cn":"有良好的开端;顺利开始","en":"If someone or something gets off to a flying start, or makes a flying start, they start very well, for example in a race or a new job.","ex":{"en":"Advertising revenue in the new financial year has got off to a flying start","cn":"广告收入在新财年取得了开门红。"}}]},"examples":[{"en":"She passed the exam with flying colours.","cn":"她以优异成绩通过了考试。"},{"en":"I'm terrified of flying.","cn":"我十分害怕坐飞机。"}],"base":"fly"},"flash":{"media":{"img":["media/pic/creativehobbies_comp.jpg","media/thumb/photography.jpg"],"uk":"media/uk/flash__gb_1.mp3","us":"media/us/flash__us_1.mp3"},"oxford":{"phon":"flæʃ","pos":"noun","senses":[{"en":"a sudden bright light that shines for a moment and then disappears","cn":"闪光；闪耀","g":"[countable]","sc":"light","ex":{"en":"a flash of lightning","cn":"一道闪电"}},{"en":"the act of shining a light on something, especially as a signal","cn":"（尤指信号灯）闪亮","g":"[countable]","sc":"signal","ex":{"en":"The lighthouse gives out four flashes every 15 seconds.","cn":"灯塔每 15 秒闪亮四次。"}},{"en":"a piece of equipment that produces a bright light for a very short time, used for taking photographs indoors, when it is dark, etc.; the use of this when taking a photograph","cn":"闪光灯","g":"[countable, uncountable]","sc":"in photography","ex":{"en":"a camera with a built-in flash","cn":"有内置闪光灯的照相机"}},{"en":"the sudden appearance for a short time of something bright","cn":"（明亮的东西）闪现","g":"[countable]","sc":"of bright colour","ex":{"en":"a flash of white teeth","cn":"闪露洁白的牙齿"}},{"en":"a particular idea or feeling that suddenly comes into your mind or shows in your face","cn":"（想法的）突现；（情感的）突发","g":"[countable]","sc":"sudden idea/emotion","ex":{"en":"a flash of brilliance/insight/inspiration","cn":"灵光一现/洞察力/灵感"}},{"en":"a short item of important news that is broadcast on radio or television, often interrupting a programme","cn":"（插播的）简明新闻，快讯","g":"[countable]","lab":"especially British English","sc":"news"},{"en":"a band or small piece of cloth worn on a military uniform to show a person’s rank","cn":"（佩戴在军服上的）徽章，肩章，臂章","g":"[countable]","lab":"British English","sc":"on uniform"},{"en":"a band of colour or writing across a book, pack, etc.","cn":"彩条；文字条","g":"[countable]","sc":"on book/pack"},{"en":"a program that creates moving images for websites","cn":"Flash 网站动画制作程序","g":"[uncountable]","sc":"computing"},{"en":"to shine very brightly for a short time; to make something shine in this way","cn":"（使）闪耀，闪光","g":"[intransitive, transitive]","sc":"shine brightly","ex":{"en":"Lightning flashed in the distance.","cn":"远处电光闪闪。"},"pos":"verb"},{"en":"to use a light to give somebody a signal","cn":"（向…）用光发出（信号）","g":"[transitive, intransitive]","sc":"give signal","ex":{"en":"Red lights flashed a warning at them.","cn":"红灯闪亮向他们发出警告。"},"pos":"verb"},{"en":"to show something to somebody quickly","cn":"（快速地）出示，显示","g":"[transitive]","sc":"show quickly","ex":{"en":"He flashed his pass at the security officer.","cn":"他向保安员亮了一下通行证。"},"pos":"verb"},{"en":"to move or pass very quickly","cn":"飞速运动；掠过","g":"[intransitive]","sc":"move quickly","ex":{"en":"The countryside flashed past the train windows.","cn":"乡村景色从火车窗外飞掠而过。"},"pos":"verb"},{"en":"to come into your mind suddenly","cn":"突然想到；猛然想起","g":"[intransitive]","sc":"of thoughts/memories","ex":{"en":"A terrible thought flashed through my mind.","cn":"一个可怕的想法闪过我的脑海。"},"pos":"verb"},{"en":"to appear on a television screen, computer screen, etc. for a short time; to make something do this","cn":"（使）闪现，映出，显示","g":"[intransitive, transitive]","sc":"on screen","ex":{"en":"A message was flashing on the screen.","cn":"屏幕上闪现出一则信息。"},"pos":"verb"},{"en":"to send information quickly by radio, computer, etc.","cn":"（通过无线电、计算机等）快速发送（信息）","g":"[transitive]","sc":"send news","ex":{"en":"News of their triumph was flashed around the world.","cn":"他们胜利的消息迅速传遍了全世界。"},"pos":"verb"},{"en":"to show a strong emotion suddenly and quickly","cn":"突然显露（强烈情感）","g":"[intransitive]","lab":"literary","sc":"show emotion","ex":{"en":"Her eyes flashed with anger.","cn":"她眼中闪出怒火。"},"pos":"verb"},{"en":"to show the sexual organs in public","cn":"当众暴露性器官","g":"[intransitive]","lab":"informal","sc":"of a man","pos":"verb"},{"en":"attracting attention by being large or expensive, or by having expensive clothes, etc.","cn":"庞大的；昂贵的；穿着奢华的","ex":{"en":"a flash car","cn":"外表华丽的轿车"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"闪耀;闪光","en":"A flash is a sudden burst of light or of something shiny or bright.","ex":{"en":"A sudden flash of lightning lit everything up for a second","cn":"突然一个闪电瞬间照亮了一切。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)闪光,(使)闪耀;(尤指)频闪","en":"If a light flashes or if you flash a light, it shines with a sudden bright light, especially as quick, regular flashes of light.","ex":{"en":"Lightning flashed among the distant dark clouds","cn":"一道道电光在远处的乌云中闪现。"}},{"pos":"N-COUNT 可数名词","cn":"突发;忽然的一阵","en":"You talk about a flash of something when you are saying that it happens very suddenly and unexpectedly.","ex":{"en":"'What did Moira tell you?' Liz demanded with a flash of anger","cn":"“莫伊拉跟你说什么啦？”利兹突然生气地质问道。"}},{"pos":"VERB 动词","cn":"飞快移动;飞驰;掠过","en":"If something flashes past or by, it moves past you so fast that you cannot see it properly.","ex":{"en":"It was a busy road, cars flashed by every few minutes.","cn":"这是一条繁忙的道路，每隔几分钟就有汽车飞驰而过。"}},{"pos":"VERB 动词","cn":"突然闪过(脑海)","en":"If something flashes through or into your mind, you suddenly think about it.","ex":{"en":"A ludicrous thought flashed through Harry's mind","cn":"一个荒谬的念头突然在哈里脑中闪现。"}},{"pos":"VERB 动词","cn":"一晃亮出;快速出示","en":"If you flash something such as an identity card, you show it to people quickly and then put it away again.","ex":{"en":"Halim flashed his official card, and managed to get hold of a soldier to guard the Land Rover.","cn":"哈利姆亮了一下他的军官证，设法找来了一名士兵看着路虎车。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)闪现;(使)出现;(使)显示","en":"If a picture or message flashes up on a screen, or if you flash it onto a screen, it is displayed there briefly or suddenly, and often repeatedly.","ex":{"en":"The figures flash up on the scoreboard","cn":"数字显示在记分牌上。"}},{"pos":"VERB 动词","cn":"(通过计算机、卫星或其他系统)快速发送，迅速播出，传送","en":"If you flash news or information to a place, you send it there quickly by computer, satellite, or other system.","ex":{"en":"They had told their offices to flash the news as soon as it broke","cn":"他们已经告诉各办公室，一有消息立即发布。"}},{"pos":"VERB 动词","cn":"瞥(一眼);投之(一笑)","en":"If you flash a look or a smile at someone, you suddenly look at them or smile at them.","ex":{"en":"I flashed a look at Sue","cn":"我向休瞥了一眼。"}},{"pos":"VERB 动词","cn":"(眼睛尤因气愤)发光，发亮","en":"If someone's eyes flash, they suddenly show a strong emotion, especially anger.","ex":{"en":"Her dark eyes flashed and she spoke rapidly.","cn":"她飞快地说着，黑色的双眼放着光。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(摄影时的)闪光灯","en":"Flash is the use of special bulbs to give more light when taking a photograph.","ex":{"en":"He was one of the first people to use high speed flash in bird photography.","cn":"他是最先使用高速闪光灯拍摄鸟类的人之一。"}},{"pos":"N-COUNT 可数名词","cn":"同 flashlight","en":"A flash is the same as a flashlight .","ex":{"en":"Stopping to rest, Pete shut off the flash.","cn":"皮特关掉手电筒，停下来休息。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奢华的;时髦的;新潮的","en":"If you describe something as flash, you mean that it looks expensive, fashionable, and new.","ex":{"en":"...a flash uptown restaurant","cn":"城郊富人区的豪华饭店"}},{"pos":"PHRASE 短语","cn":"昙花一现","en":"If you describe an achievement or success as a flash in the pan, you mean that it is unlikely to be repeated and is not an indication of future achievements or success.","ex":{"en":"People will be looking in to see how good we are now and whether our success has just been a flash in the pan.","cn":"人们会来看看我们现在有多成功，看看我们的成功是否只是昙花一现。"}},{"pos":"PHRASE 短语","cn":"转瞬;一瞬间","en":"If you say that something happens in a flash, you mean that it happens suddenly and lasts only a very short time.","ex":{"en":"The answer had come to him in a flash","cn":"他一下子就有了答案。"}},{"pos":"PHRASE 短语","cn":"(反应)飞快，迅速","en":"If you say that someone reacts to something quick as a flash, you mean that they react to it extremely quickly.","ex":{"en":"Quick as a flash, the man said, 'I have to, don't I?'","cn":"那人立即说道：“我必须如此，是不是？”"}},{"pos":"PHRASAL VERB 短语动词","cn":"突然记起;猛然想起;忽地记起","en":"If your mind flashes back to something in the past, you remember it or think of it briefly or suddenly.","ex":{"en":"His mind kept flashing back to the previous night","cn":"他脑中不断回想起头天晚上发生的事。"}},{"pos":"","cn":"","en":"相关词组：flash back"}]},"examples":[{"en":"It flashed on me that he was the man I'd seen in the hotel.","cn":"我顿时认出他就是我在旅馆里看到的那个人。"},{"en":"There was a blinding flash and the whole building shuddered.","cn":"一道眩目的闪光过后，整栋大楼颤抖起来。"}]},"flu":{"oxford":{"phon":"fluː","pos":"noun","senses":[{"en":"a serious disease caused by a virus, that causes a high temperature, severe pains and weakness","cn":"流行性感冒；流感","lab":"British English","ex":{"en":"The whole family has the flu.","cn":"全家都患了流感。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"流感","en":"Flu is an illness which is similar to a bad cold but more serious. It often makes you feel very weak and makes your muscles hurt.","ex":{"en":"I got flu","cn":"我得了流感。"}}]},"media":{"uk":"media/uk/flu__gb_1.mp3","us":"media/us/flu__us_1.mp3"},"examples":[{"en":"The whole family has the flu.","cn":"全家都患流感。"},{"en":"( BrE ) She's got flu.","cn":"她患上了流感。"}]},"flimsy":{"media":{"uk":"media/uk/flimsy__gb_1.mp3","us":"media/us/flimsy__us_1.mp3"},"oxford":{"phon":"ˈflɪmzi","pos":"adjective","senses":[{"en":"badly made and not strong enough for the purpose for which it is used","cn":"劣质的；不结实的","ex":{"en":"a flimsy table","cn":"不结实的桌子"}},{"en":"thin and easily torn","cn":"薄而易损坏的","ex":{"en":"a flimsy piece of paper/fabric/plastic","cn":"薄薄的一张纸／一块织物／一片塑料"}},{"en":"difficult to believe","cn":"不足信的","ex":{"en":"a flimsy excuse/explanation","cn":"站不住脚的借口／解释"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不结实的;劣质的;不牢固的","en":"A flimsy object is weak because it is made of a weak material, or is badly made.","ex":{"en":"...a flimsy wooden door.","cn":"很不结实的木门"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服或布料)薄的，不御寒的","en":"Flimsy cloth or clothing is thin and does not give much protection.","ex":{"en":"...a very flimsy pink chiffon nightgown.","cn":"薄如蝉翼的粉色雪纺绸睡衣"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"站不住脚的;不足信的","en":"If you describe something such as evidence or an excuse as flimsy, you mean that it is not very good or convincing.","ex":{"en":"The charges were based on very flimsy evidence.","cn":"这些指控建立在非常不具说服力的证据上。"}}]},"examples":[{"en":"The evidence against him is pretty flimsy.","cn":"对他不利的证据很难站住脚。"},{"en":"a flimsy piece of paper/fabric/plastic","cn":"薄薄的一张纸/一块织物/一片塑料"}]},"flawed":{"media":{"uk":"media/uk/flawed__gb_1.mp3","us":"media/us/flawed__us_1.mp3"},"oxford":{"phon":"flɔːd","pos":"adjective","senses":[{"en":"having a flaw; not perfect or correct","cn":"有错误的；有缺点的；有瑕疵的","ex":{"en":"seriously/fundamentally/fatally flawed","cn":"有严重／根本／致命缺点"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有瑕疵的;有错误的;有缺陷的","en":"Something that is flawed has a mark, fault, or mistake in it.","ex":{"en":"...the unique beauty of a flawed object","cn":"有瑕疵物品的独特美"}}]},"examples":[{"en":"seriously/fundamentally/fatally flawed","cn":"有严重/根本/致命缺点"},{"en":"the book's flawed heroine","cn":"书中有弱点的女主角"}]},"flood":{"media":{"uk":"media/uk/flood__gb_1.mp3","us":"media/us/flood__us_1.mp3"},"oxford":{"phon":"flʌd","pos":"noun","senses":[{"en":"a large amount of water covering an area that is usually dry","cn":"洪水；水灾","g":"[countable, uncountable]","sc":"water","ex":{"en":"The heavy rain has caused floods in many parts of the country.","cn":"大雨使全国许多地方泛滥成灾。"}},{"en":"a very large number of things or people that appear at the same time","cn":"大批，大量（的人或事物）","g":"[countable]","sc":"large number","ex":{"en":"a flood of complaints","cn":"大量投诉"}},{"en":"the great flood that covered the world in the Bible story","cn":"（圣经）灭世洪水","g":"[singular]","sc":"in Bible","ex":{"en":"before the Flood (= a very long time ago)","cn":"洪水之前（=很久以前）"}},{"en":"if a place floods or something floods it, it becomes filled or covered with water","cn":"（使）灌满水；淹没","g":"[intransitive, transitive]","sc":"fill with water","ex":{"en":"The cellar floods whenever it rains heavily.","cn":"只要一下大雨地窖就淹水。"},"pos":"verb"},{"en":"to become so full that it spreads out onto the land around it","cn":"泛滥；淹没","g":"[intransitive, transitive]","sc":"of river","ex":{"en":"When the Ganges floods, it causes considerable damage.","cn":"恒河泛滥时造成严重损害。"},"pos":"verb"},{"en":"to arrive or go somewhere in large numbers","cn":"大量涌入；蜂拥而出","g":"[intransitive]","sc":"large numbers","ex":{"en":"The home fans flooded onto the pitch at the finish.","cn":"比赛结束后，主场球迷涌入球场。"},"pos":"verb"},{"en":"to send something somewhere in large numbers","cn":"大量送至；挤满；拥满","g":"[transitive, usually passive]","sc":"large numbers","ex":{"en":"The office was flooded with applications for the job.","cn":"办公室堆满了应聘该职位的求职信。"},"pos":"verb"},{"en":"to become or make something become available in a place in large numbers","cn":"（使）充斥，充满","g":"[transitive]","sc":"large numbers","ex":{"en":"Cheap imported goods are flooding the market.","cn":"廉价进口商品充斥着市场。"},"pos":"verb"},{"en":"to affect somebody suddenly and strongly","cn":"使大受感动；充满","g":"[intransitive, transitive]","sc":"of feeling/thought","ex":{"en":"A great sense of relief flooded over him.","cn":"他深感宽慰。"},"pos":"verb"},{"en":"to spread suddenly into something; to cover something","cn":"照进；覆盖","g":"[intransitive, transitive]","sc":"of light/colour","ex":{"en":"She drew the curtains and the sunlight flooded in.","cn":"她拉开窗帘，阳光洒了进来。"},"pos":"verb"},{"en":"if an engine floods or if you flood it, it becomes so full of petrol that it will not start","cn":"（使）溢流","g":"[intransitive, transitive]","sc":"engine","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"洪水;水灾","en":"If there is a flood, a large amount of water covers an area which is usually dry, for example when a river flows over its banks or a pipe bursts.","ex":{"en":"More than 70 people were killed in the floods, caused when a dam burst","cn":"大坝决口造成洪灾，70 多人因此丧生。"}},{"pos":"V-ERG 及物/不及物动词","cn":"淹没;使充满水","en":"If something such as a river or a burst pipe floods an area that is usually dry or if the area floods, it becomes covered with water.","ex":{"en":"The Chicago River flooded the city's underground tunnel system","cn":"芝加哥河的河水淹没了城市的地下隧道系统。"}},{"pos":"VERB 动词","cn":"(尤指暴雨后河水)泛滥","en":"If a river floods, it overflows, especially after very heavy rain.","ex":{"en":"...the relentless rain that caused twenty rivers to flood","cn":"引发了 20 条河流泛滥的持续降水"}},{"pos":"N-COUNT 可数名词","cn":"大量;大批","en":"If you say that a flood of people or things arrive somewhere, you are emphasizing that a very large number of them arrive there.","ex":{"en":"The administration is trying to stem the flood of refugees out of Haiti and into Florida","cn":"政府当局正试图阻止大批难民逃离海地，进入佛罗里达。"}},{"pos":"VERB 动词","cn":"大批涌入;大量云集","en":"If you say that people or things flood into a place, you are emphasizing that they arrive there in large numbers.","ex":{"en":"Large numbers of immigrants flooded into the area","cn":"大量移民涌入这个地区。"}},{"pos":"VERB 动词","cn":"(使)充满;(使)充斥","en":"If you flood a place with a particular type of thing, or if a particular type of thing floods a place, the place becomes full of so many of them that it cannot hold or deal with any more.","ex":{"en":"...a policy aimed at flooding Europe with exports","cn":"一项旨在让进口产品充斥欧洲市场的政策"}},{"pos":"VERB 动词","cn":"(情感等)充满，使感受强烈，涌上心头","en":"If an emotion, feeling, or thought floods you, you suddenly feel it very intensely. If feelings or memories flood back, you suddenly remember them very clearly.","ex":{"en":"A wave of happiness flooded me","cn":"我心中涌起一股幸福的暖流。"}},{"pos":"VERB 动词","cn":"(光线)充满，照进","en":"If light floods a place or floods into it, it suddenly fills it.","ex":{"en":"The afternoon light flooded the little rooms","cn":"午后的阳光洒满一间间小屋。"}},{"pos":"PHRASE 短语","cn":"(河水)泛滥","en":"If a river is in flood, it is flowing over its banks because it has more water in it than normal."},{"pos":"PHRASE 短语","cn":"泪如雨下;号啕大哭","en":"If you say that someone was in floods of tears or in a flood of tears, you are emphasizing that they were crying with great intensity because they were very upset.","ex":{"en":"The pain was so bad that I would be in floods of tears","cn":"疼痛难忍，我就快大哭起来了。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(洪水)迫使…离开，淹没，冲毁","en":"If people, places, or things are flooded out, the water from a flood makes it impossible for people to stay in that place or to use that thing.","ex":{"en":"Train lines were flooded out","cn":"铁路线被洪水冲毁。"}},{"pos":"","cn":"","en":"相关词组：flood out"}]},"examples":[{"en":"A man who planned to flood Britain with cocaine was jailed for 15 years.","cn":"一个企图在英国大量销售可卡因的男人被判刑 15 年。"},{"en":"Police have issued flood warnings for Nevada.","cn":"警方已经发布了内华达州的水灾警告。"}]},"flooding":{"media":{"uk":"media/uk/flooding__gb_1.mp3","us":"media/us/flooding__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"洪水泛滥;水灾","en":"If flooding occurs, an area of land that is usually dry is covered with water after heavy rain or after a river or lake flows over its banks.","ex":{"en":"The flooding, caused by three days of torrential rain, is the worst in sixty-five years.","cn":"连续 3 天的倾盆大雨引发的洪水是 65 年来最严重的一次。"}}]},"examples":[{"en":"There will be heavy rain with flooding in some areas.","cn":"将有大雨，有些地方会泛滥成灾。"},{"en":"The heavy rain has led to serious flooding in some areas.","cn":"大雨造成部分地区发生严重水灾。"}],"oxford":{"phon":"ˈflʌdɪŋ","pos":"noun","senses":[{"en":"large amounts of water covering an area that is usually dry; the fact of this happening","cn":"洪水；水灾","ex":{"en":"There will be heavy rain with flooding in some areas.","cn":"将会有大雨，局部区域可能引发水灾。"}}]},"base":"flood"},"flexibility":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to change or be changed easily to suit a different situation","cn":"灵活性"},{"en":"the ability to bend or be bent easily","cn":"弹性﹐柔韧性"}]},"examples":[{"en":"Employees expect flexibility in the workplace.","cn":"员工们期望能够灵活办公。","src":"ld"},{"en":"Stretching exercises will help your flexibility.","cn":"伸展运动能增强身体柔韧性。","src":"ld"}],"media":{"uk":"media/uk/flexibility__gb_1.mp3","us":"media/us/flexibility__us_1.mp3"},"oxford":{"phon":"ˌfleksəˈbɪləti","pos":"noun","senses":[{"en":"the ability to change to suit new conditions or situations","cn":"灵活；弹性","lab":"approving","ex":{"en":"The new system offers a much greater degree of flexibility in the way work is organized.","cn":"新系统使工作安排灵活多了。"}},{"en":"the ability to bend easily without breaking","cn":"柔韧；弹性","ex":{"en":"exercises to develop the flexibility of dancers’ bodies","cn":"增加跳舞者身体柔软度的训练动作"}}]}},"flavours":{"lemma":"flavour"},"flattering":{"media":{"uk":"media/uk/flattering__gb_1.mp3","us":"media/us/flattering__us_1.mp3"},"oxford":{"phon":"ˈflætərɪŋ","pos":"adjective","senses":[{"en":"making somebody look more attractive","cn":"使人显得更漂亮的","ex":{"en":"a flattering dress","cn":"穿上去使人更漂亮的连衣裙"}},{"en":"saying nice things about somebody/something","cn":"奉承的；阿谀的；讨好的","ex":{"en":"He made several flattering remarks.","cn":"他说了几句奉承话。"}},{"en":"making somebody feel pleased and special","cn":"奉承的；使人感到荣幸的","ex":{"en":"I found it flattering that he still recognized me after all these years.","cn":"过了这么多年他还认得我，使我觉得荣幸。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人显得更漂亮的","en":"If something is flattering, it makes you appear more attractive.","ex":{"en":"Some styles are so flattering that they instantly become classics","cn":"有些款式特别衬人，很快就成了经典。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"谄媚的;奉承的;讨好的","en":"If someone's remarks are flattering, they praise you and say nice things about you.","ex":{"en":"There were pleasant and flattering obituaries about him","cn":"讣告里全是对他的客套溢美之词。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奉承的;令人感到荣幸的","en":"If you describe something as flattering, you mean that it pleases you and makes you feel important or special.","ex":{"en":"It is all terribly flattering and she is trying to reply to every single letter personally","cn":"一切都让她感到无比荣幸，她尽量亲自回复每一封信。"}}]},"examples":[{"en":"I found it flattering that he still recognized me after all these years.","cn":"过了这么多年他还认得我，使我觉得荣幸。"},{"en":"a flattering dress","cn":"穿上去使人更漂亮的连衣裙"}],"base":"flatter"},"flavour":{"oxford":{"phon":"ˈfleɪvə(r)","pos":"noun","senses":[{"en":"how food or drink tastes","cn":"（食物或饮料的）味道","g":"[uncountable]","ex":{"en":"The tomatoes give extra flavour to the sauce.","cn":"番茄使调味汁别有风味。"}},{"en":"a particular type of taste","cn":"（某种）味道","g":"[countable]","ex":{"en":"This yogurt comes in ten different flavours.","cn":"这种酸奶有十种不同的味道。"}},{"en":"a substance added to food or drink to give it a particular taste","cn":"调味品；调味香料","g":"[uncountable, countable]","lab":"North American English"},{"en":"a particular quality or atmosphere","cn":"特点；特色；气氛","g":"[singular]","ex":{"en":"the distinctive flavour of South Florida","cn":"南佛罗里达的独特风情"}},{"en":"an idea of what something is like","cn":"像…的想法","g":"[singular]","ex":{"en":"I have tried to convey something of the flavour of the argument.","cn":"我试图传达某种类似论据的东西。"}},{"en":"a particular type of something, especially computer software","cn":"衍生系统","lab":"computing"},{"en":"to add something to food or drink to give it more taste or a particular taste","cn":"给（食物或饮料）调味；加味于","ex":{"en":"This dish is flavoured with basil and garlic.","cn":"这道菜用了罗勒和大蒜调味。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"味;滋味;味道","en":"The flavour of a food or drink is its taste.","ex":{"en":"This cheese has a crumbly texture with a strong flavour","cn":"这种奶酪口感松脆，味道浓郁。"}},{"pos":"N-COUNT 可数名词","cn":"(食物等的)口味，味道","en":"If something is orange flavour or beef flavour, it is made to taste of orange or beef.","ex":{"en":"...salt and vinegar flavour crisps.","cn":"咸酸口味的炸薯片"}},{"pos":"VERB 动词","cn":"给…调味;加味于","en":"If you flavour food or drink, you add something to it to give it a particular taste.","ex":{"en":"Flavour your favourite dishes with exotic herbs and spices","cn":"把异国风味的芳草和香料加到你最喜爱的菜肴里调味。"}},{"pos":"N-COUNT 可数名词","cn":"特色;风味;风格","en":"You can refer to a special quality that something has as its flavour. For example, if something has an Italian flavour it reminds you of Italian things.","ex":{"en":"...a car with a flavour that is distinctly Italian.","cn":"带有明显意大利风格的轿车"}},{"pos":"N-SING 单数名词","cn":"大体介绍;概述;概念","en":"If something gives you a flavour of a subject, situation, or event, it gives you a general idea of what it is like.","ex":{"en":"The book gives you a flavour of what alternative therapy is about.","cn":"这本书让你大致了解一下什么是替代疗法。"}},{"pos":"PHRASE 短语","cn":"红极一时的人物;风靡一时的事物","en":"If you think that something or someone is very popular at a particular time, you can say that they are flavour of the month .","ex":{"en":"Hats were very much flavour of the month","cn":"帽子在当时是时尚热宠。"}}]},"media":{"uk":"media/uk/flavour__gb_1.mp3","us":"media/us/flavour__us_1.mp3"},"examples":[{"en":"Foreign visitors help to give a truly international flavour to the occasion.","cn":"外国客人使这个场合显出一种真正国际性的气氛。"},{"en":"I have tried to convey something of the flavour of the argument.","cn":"我试图表达某种类似论据的东西。"}]},"floor":{"media":{"uk":"media/uk/floor__gb_1.mp3","us":"media/us/floor__us_1.mp3"},"oxford":{"phon":"flɔː(r)","pos":"noun","senses":[{"en":"the surface of a room that you walk on","cn":"地板；地面","g":"[countable, usually singular]","sc":"of room","ex":{"en":"a wooden/concrete/tiled floor","cn":"木地板；水泥／瓷砖地面"}},{"en":"the bottom surface of a vehicle","cn":"（车辆的）地板","g":"[countable, usually singular]","lab":"North American English also","sc":"of vehicle","ex":{"en":"The floor of the car was covered in cigarette ends.","cn":"小轿车地板上满是烟蒂。"}},{"en":"all the rooms that are on the same level of a building","cn":"楼层","g":"[countable]","lab":"British English","sc":"level of building","ex":{"en":"Their apartment occupies the top floor of the building.","cn":"他们的公寓位于大楼的顶层。"}},{"en":"the ground at the bottom of the sea, a forest, etc.","cn":"（海等的）底；（森林等的）地面","g":"[countable, usually singular]","sc":"of the sea/forests","ex":{"en":"the ocean/sea/forest floor","cn":"洋底；海底；林地表层"}},{"en":"the part of a building where discussions or debates are held, especially in a parliament; the people who attend a discussion or debate","cn":"议员席；全体议员；全体与会者","g":"[singular]","sc":"in parliament, etc.","ex":{"en":"Opposition politicians registered their protest on the floor of the House.","cn":"反对党从政者在议院的议员席提出了抗议。"}},{"en":"an area in a building that is used for a particular activity","cn":"（建筑物内的）场地","g":"[countable, usually singular]","sc":"area for work","ex":{"en":"on the floor of the Stock Exchange (= where trading takes place)","cn":"在证券交易所的交易厅"}},{"en":"the lowest level allowed for wages or prices","cn":"（工资或物价的）最低额，底价","g":"[countable, usually singular]","sc":"for wages/prices","ex":{"en":"Prices have gone through the floor (= fallen to a very low level).","cn":"物价已经探底。"}},{"en":"to surprise or confuse somebody so that they are not sure what to say or do","cn":"使惊奇；使困惑","sc":"surprise/confuse","ex":{"en":"His reply completely floored me.","cn":"他的回答让我彻底震惊。"},"pos":"verb"},{"en":"to make somebody fall down by hitting them, especially in a sport","cn":"（尤指体育运动中）击倒，打倒","g":"[usually passive]","sc":"hit","ex":{"en":"He was floored by the first punch.","cn":"才挨第一拳，他就被击倒了。"},"pos":"verb"},{"en":"to provide a building or room with a floor","cn":"给…安装地板；给…铺设地面","g":"[usually passive]","sc":"building/room","ex":{"en":"All of the rooms are floored in solid pine.","cn":"所有的房间都铺上了纯松木地板。"},"pos":"verb"},{"en":"to press the accelerator pedal of a car hard","cn":"把（汽车的油门踏板）踩到底","sc":"driving","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地面;地板","en":"The floor of a room is the part of it that you walk on.","ex":{"en":"Jack's sitting on the floor watching TV","cn":"杰克正坐在地板上看电视。"}},{"pos":"N-COUNT 可数名词","cn":"层;楼层","en":"A floor of a building is all the rooms that are on a particular level.","ex":{"en":"It is on the fifth floor of the hospital","cn":"它位于医院的5层。"}},{"pos":"N-COUNT 可数名词","cn":"(海洋、山谷的)底部","en":"The ocean floor is the ground at the bottom of an ocean. The valley floor is the ground at the bottom of a valley.","ex":{"en":"They spend hours feeding on the ocean floor.","cn":"它们花好几个小时在海底进食。"}},{"pos":"N-COUNT 可数名词","cn":"议事厅;(尤指)议员席","en":"The place where official debates and discussions are held, especially between members of parliament, is referred to as the floor .","ex":{"en":"The issues were debated on the floor of the House.","cn":"这些问题在议院的议员席进行了讨论。"}},{"pos":"N-SING-COLL 单数集合名词","cn":"(辩论或讨论的)听众席","en":"In a debate or discussion, the floor is the people who are listening to the arguments being put forward but who are not among the main speakers.","ex":{"en":"The president is taking questions from the floor.","cn":"总统正接受来自听众席的提问。"}},{"pos":"N-COUNT 可数名词","cn":"(证券)交易大厅，交易所","en":"The floor of a stock exchange is the large open area where trading is done.","ex":{"en":"...the dealing floor at Standard Chartered Bank.","cn":"渣打银行的交易大厅"}},{"pos":"N-COUNT 可数名词","cn":"舞池","en":"The floor in a place such as a club or disco is the area where people dance."},{"pos":"VERB 动词","cn":"使困惑;使不知所措","en":"If you are floored by something, you are unable to respond to it because you are so surprised by it.","ex":{"en":"He was floored by the announcement","cn":"这个通告使他不知所措。"}},{"pos":"VERB 动词","cn":"(尤指在拳击比赛中)打倒，击倒","en":"If someone is floored, especially in boxing, they are hit so hard that they fall over.","ex":{"en":"He was floored twice in the second round.","cn":"在第二轮中他两次被打倒在地。"}},{"pos":"PHRASE 短语","cn":"(在辩论或讨论中)发言/给予…发言权","en":"If you take the floor, you start speaking in a debate or discussion. If you are given the floor, you are allowed to do this.","ex":{"en":"Ministers took the floor to denounce the decision to suspend constitutional rule","cn":"几位部长发言谴责暂停宪制的决定。"}},{"pos":"PHRASE 短语","cn":"起舞;开始跳舞","en":"If you take to the floor, you start dancing at a dance or disco.","ex":{"en":"The happy couple and their respective parents took to the floor.","cn":"这对幸福的新人和他们各自的父母在舞池中翩翩起舞。"}},{"pos":"PHRASE 短语","cn":"(价格或销售)突然下滑，陡降","en":"If you say that prices or sales have fallen through the floor, you mean that they have suddenly decreased.","ex":{"en":"Property prices have dropped through the floor","cn":"房地产价格骤降。"}},{"pos":"PHRASE 短语","cn":"彻底击败;完全打败","en":"If you wipe the floor with someone, you defeat them completely in a competition or discussion.","ex":{"en":"He could wipe the floor with the Prime Minister.","cn":"他能彻底击败首相。"}}]},"examples":[{"en":"Opposition politicians registered their protest on the floor of the House.","cn":"反对党从政者在议院的议员席提出了抗议。"},{"en":"The alterations should give us extra floor space.","cn":"这些改动应该使我们有更大的居住面积。"}]},"flight":{"media":{"uk":"media/uk/flight__gb_1.mp3","us":"media/us/flight__us_1.mp3"},"oxford":{"phon":"flaɪt","pos":"noun","senses":[{"en":"a journey made by air, especially in a plane","cn":"（尤指乘飞机的）空中航行，航程","g":"[countable]","lab":"figurative","sc":"journey by air","ex":{"en":"a smooth/comfortable/bumpy flight","cn":"平稳／舒适／颠簸的空中航行"}},{"en":"a plane making a particular journey","cn":"航班飞机；班机","g":"[countable]","lab":"British English","sc":"plane","ex":{"en":"We're booked on the same flight.","cn":"我们订了同一班机的机票。"}},{"en":"the act of flying","cn":"飞行；飞翔","g":"[uncountable]","sc":"flying","ex":{"en":"the age of supersonic flight","cn":"超声速飞行时代"}},{"en":"the movement or direction of an object as it travels through the air","cn":"（物体的）飞行，飞行方向","g":"[uncountable]","sc":"movement of object","ex":{"en":"the flight of a ball","cn":"球的飞行"}},{"en":"a series of steps between two floors or levels","cn":"一段楼梯；一段阶梯","g":"[countable]","sc":"of steps","ex":{"en":"She fell down a flight of stairs/steps and hurt her back.","cn":"她从一段楼梯上跌了下来，摔伤了背。"}},{"en":"the act of running away from a dangerous or difficult situation","cn":"（从危险或困境中的）逃避，躲避","g":"[uncountable, singular]","sc":"running away","ex":{"en":"the flight of refugees from the advancing forces","cn":"难民躲避挺进的军队"}},{"en":"an idea or a statement that shows a lot of imagination but is not practical or sensible","cn":"异想天开；奇思怪想","g":"[countable]","sc":"of fancy/imagination","ex":{"en":"This idea was one of my wilder flights of fancy.","cn":"这个想法是我最疯狂的幻想之一。"}},{"en":"a group of birds or aircraft flying together","cn":"（一起飞行的）鸟群（或机群）","g":"[countable]","sc":"group of birds/aircraft","ex":{"en":"a flight of geese","cn":"一队飞雁"}},{"en":"to kick, hit or throw a ball through the air with skill","cn":"（熟练地踢、击或掷）使（球）在空中飞行","ex":{"en":"He equalized with a beautifully flighted shot.","cn":"他漂亮的凌空一击把比分扳平。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"飞行;航行","en":"A flight is a journey made by flying, usually in an aeroplane.","ex":{"en":"The flight will take four hours.","cn":"这次航行要飞 4 个小时。"}},{"pos":"N-COUNT 可数名词","cn":"航班;客机","en":"You can refer to an aeroplane carrying passengers on a particular journey as a particular flight .","ex":{"en":"I'll try to get on the flight down to Karachi tonight","cn":"我尽量赶上今晚去卡拉奇的航班。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"飞行;飞行能力","en":"Flight is the action of flying, or the ability to fly.","ex":{"en":"These hawks are magnificent in flight, soaring and circling for long periods","cn":"这些鹰飞行能力极其出色，可以长时间在空中翱翔和盘旋。"}},{"pos":"N-COUNT 可数名词","cn":"鸟群","en":"A flight of birds is a group of them flying together.","ex":{"en":"A flight of green parrots shot out of the cedar forest.","cn":"一群绿鹦鹉从杉木林里疾速飞出。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"逃避;躲开","en":"Flight is the act of running away from a dangerous or unpleasant situation or place.","ex":{"en":"Frank was in full flight when he reached them","cn":"弗兰克正在拼命奔逃，这时他联系到了他们。"}},{"pos":"N-COUNT 可数名词","cn":"一段(台阶或楼梯)","en":"A flight of steps or stairs is a set of steps or stairs that lead from one level to another without changing direction.","ex":{"en":"We walked in silence up a flight of stairs and down a long corridor.","cn":"我们默默地走上一段楼梯，穿过一个长长的走廊。"}},{"pos":"PHRASE 短语","cn":"想入非非;异想天开","en":"An idea or statement that is very imaginative but complicated, silly, or impractical can be referred to as a flight of fancy .","ex":{"en":"Cockburn engaged in a flight of fancy, never once allowing facts to get in the way.","cn":"科伯恩一直在想入非非，从不曾考虑现实状况。"}},{"pos":"PHRASE 短语","cn":"逃走;逃离;逃避","en":"If someone takes flight, they run away from an unpleasant situation or place.","ex":{"en":"He was told of the raid and decided to take flight immediately.","cn":"他得知要突击搜查，决定立刻逃走。"}}]},"examples":[{"en":"mercy/relief flights (= planes taking help to countries where there is a war)","cn":"急救/救援班机（运送救援物资至发生战争的国家）"},{"en":"The bird is easily recognized in flight (= when it is flying) by the black band at the end of its tail.","cn":"这种鸟尾部末端有一条黑带，飞翔时很容易认出来。"}]},"flat":{"media":{"img":["media/pic/homes_comp.jpg","media/thumb/flat.jpg"],"uk":"media/uk/flat__gb_1.mp3","us":"media/us/flat__us_1.mp3"},"oxford":{"phon":"flæt","pos":"noun","senses":[{"en":"a set of rooms for living in, usually on one floor of a building","cn":"一套房子；公寓；单元房","g":"[countable]","lab":"British English","sc":"rooms","ex":{"en":"They're renting a furnished flat on the third floor.","cn":"他们租了四楼一套带家具的公寓。"}},{"en":"the flat level part of something","cn":"（某物的）平面部分","g":"[singular]","sc":"level part","ex":{"en":"He beat on the door with the flat of his hand.","cn":"他用手掌打门。"}},{"en":"an area of low flat land, especially near water","cn":"（尤指水边的）平地；低洼地","g":"[countable, usually plural]","sc":"land","ex":{"en":"salt flats","cn":"盐滩"}},{"en":"the season for racing horses on flat ground with no jumps","cn":"无障碍平地赛马季节","g":"[singular]","lab":"British English","sc":"horse racing"},{"en":"a note played a semitone lower than the note that is named. The written symbol is (♭).","cn":"降半音；降音；降号","g":"[countable]","sc":"in music","ex":{"en":"There are no sharps or flats in the key of C major.","cn":"C 大调中没有升半音和降半音。"}},{"en":"a tyre that has lost air, usually because of a hole","cn":"瘪了的轮胎；撒了气的轮胎","g":"[countable]","lab":"especially North American English","sc":"tyre","ex":{"en":"We got a flat on the way home.","cn":"我们在回家的路上有一个轮胎漏气瘪了。"}},{"en":"a vertical section of scenery used on a theatre stage","cn":"平面布景；布景屏","g":"[countable]","lab":"specialist","sc":"in theatre"},{"en":"shoes with a very low heel","cn":"平跟鞋；平底鞋","g":"[plural]","lab":"informal","sc":"shoes","ex":{"en":"a pair of flats","cn":"一双平跟鞋"}},{"en":"having a level surface, not curved or sloping, and without holes or any bits sticking out","cn":"平的；平坦的","sc":"level","ex":{"en":"low buildings with flat roofs","cn":"平顶矮建筑物"},"pos":"adjective"},{"en":"without any slopes or hills","cn":"平坦的","sc":"level","ex":{"en":"The road stretched ahead across the flat landscape.","cn":"公路向前延伸，经过一片平坦的地。"},"pos":"adjective"},{"en":"calm and without waves","cn":"平的；平静无波的","sc":"level","ex":{"en":"The sails hung limply in the flat calm (= conditions at sea when there is no wind and the water is completely level).","cn":"风平浪静，风帆无力地垂挂着。"},"pos":"adjective"},{"en":"broad but not very high","cn":"扁平的","lab":"figurative","sc":"not high","ex":{"en":"Chapattis are a kind of flat Indian bread.","cn":"chapatti 是一种印度薄饼。"},"pos":"adjective"},{"en":"not exciting; not feeling or showing interest or enthusiasm","cn":"枯燥的；无趣的；缺乏热情的","sc":"not exciting","ex":{"en":"He felt very flat after his friends had gone home.","cn":"他的朋友们回家后，他感到兴味索然。"},"pos":"adjective"},{"en":"not showing much emotion; not changing much in tone","cn":"平淡的；单调的","sc":"voice","ex":{"en":"Her voice was flat and expressionless.","cn":"她的声音平淡而呆板。"},"pos":"adjective"},{"en":"very smooth, with no contrast between light and dark, and giving no impression of depth","cn":"色彩单调的；无反差的；无景深的","sc":"colours/pictures","ex":{"en":"Acrylic paints can be used to create large, flat blocks of colour.","cn":"丙烯颜料可用来创作单一色调的大幅图块。"},"pos":"adjective"},{"en":"not very successful because very little is being sold; not changing or increasing","cn":"不景气的；萧条的；没有变化的","sc":"business","ex":{"en":"The housing market has been flat for months.","cn":"房屋市场已有好几个月处于低迷状态。"},"pos":"adjective"},{"en":"not allowing discussion or argument; definite","cn":"断然的；绝对的","g":"[only before noun]","sc":"refusal/denial","ex":{"en":"Her request was met with a flat refusal.","cn":"她的请求被断然拒绝。"},"pos":"adjective"},{"en":"used after the name of a note to mean a note a semitone lower","cn":"降音的；降半音的","sc":"in music","ex":{"en":"That note should be B flat, not B.","cn":"那个音应该是降 B 音，而不是 B 音。"},"pos":"adjective"},{"en":"below the correct pitch (= how high or low a note sounds)","cn":"低于标准音高的；偏低的","sc":"in music","ex":{"en":"The high notes were slightly flat.","cn":"这些高音略为偏低。"},"pos":"adjective"},{"en":"no longer having bubbles in it; not fresh","cn":"走了气的；不新鲜的","sc":"drink","ex":{"en":"The soda was warm and had gone flat.","cn":"这汽水是温的，已走了气。"},"pos":"adjective"},{"en":"unable to supply any more electricity","cn":"电用完了的","lab":"British English","sc":"battery","pos":"adjective"},{"en":"not containing enough air, usually because of a hole","cn":"瘪了的；撒了气的","sc":"tyre","pos":"adjective"},{"en":"with no natural raised curves under the feet","cn":"扁平的；足弓平坦的","sc":"feet","pos":"adjective"},{"en":"spread out in a level, straight position, especially against another surface","cn":"（尤指贴着另一表面）平直地，平躺地","sc":"level","ex":{"en":"Lie flat and breathe deeply.","cn":"平躺做深呼吸。"},"pos":"adverb"},{"en":"in a definite and direct way","cn":"断然；直截了当地","lab":"North American English","sc":"refusing/denying","ex":{"en":"She told me flat she would not speak to me again.","cn":"她直截了当地跟我说她再不会理我了。"},"pos":"adverb"},{"en":"lower than the correct pitch (= how high or low a note sounds)","cn":"低于标准音高","sc":"in music","ex":{"en":"He sings flat all the time.","cn":"他总是唱低了音。"},"pos":"adverb"},{"en":"to live in or share a flat","cn":"住公寓；合住公寓","ex":{"en":"My sister Zoe flats in Auckland.","cn":"我妹妹佐伊住在奥克兰的一栋公寓里。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(一间)公寓;(一套)单元房","en":"A flat is a set of rooms for living in, usually on one floor and part of a larger building. A flat usually includes a kitchen and bathroom.","ex":{"en":"Sara lives with her husband and children in a flat in central London","cn":"萨拉和丈夫还有孩子们住在伦敦中心城区的一间公寓里。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平的;平展的;平滑的","en":"Something that is flat is level, smooth, or even, rather than sloping, curved, or uneven.","ex":{"en":"Tiles can be fixed to any surface as long as it's flat, firm and dry","cn":"只要表面平整、坚固而且干燥，瓷砖就可以贴住。"}},{"pos":"ADJ 形容词","cn":"水平的;非竖直的","en":"Flat means horizontal and not upright.","ex":{"en":"Two men near him threw themselves flat","cn":"他身旁的两个男人直挺挺趴倒在地上。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"浅的;不深的;矮的;扁的","en":"A flat object is not very tall or deep in relation to its length and width.","ex":{"en":"Ellen is walking down the drive with a square flat box balanced on one hand.","cn":"埃伦正一手托着一个方形的扁盒子沿私人车道走着。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地势)平的，平坦的，无起伏的","en":"Flat land is level, with no high hills or other raised parts.","ex":{"en":"To the north lie the flat and fertile farmlands of the Solway plain","cn":"北边是索尔韦平原平坦而肥沃的农田。"}},{"pos":"N-COUNT 可数名词","cn":"平地;(尤指)低洼地，浅滩","en":"A low flat area of uncultivated land, especially an area where the ground is soft and wet, can be referred to as flats or a flat .","ex":{"en":"The salt marshes and mud flats attract large numbers of waterfowl.","cn":"盐碱地和泥滩吸引了大量水鸟。"}},{"pos":"N-COUNT 可数名词","cn":"平面;平坦部分","en":"You can refer to one of the broad flat surfaces of an object as the flat of that object.","ex":{"en":"He slammed the counter with the flat of his hand.","cn":"他用手掌使劲拍打着柜台。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(鞋)平跟的，平底的","en":"Flat shoes have no heels or very low heels.","ex":{"en":"People wear slacks, sweaters, flat shoes, and all manner of casual attire for travel.","cn":"人们穿着宽松的长裤、运动衫、平底鞋和各式适合旅行的休闲服装。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(轮胎、球、气球等)瘪的，没气的","en":"A flat tyre, ball, or balloon does not have enough air in it."},{"pos":"N-COUNT 可数名词","cn":"瘪了的轮胎","en":"A flat is a tyre that does not have enough air in it.","ex":{"en":"Then, after I finally got back on the highway, I developed a flat.","cn":"后来，我终于回到公路上后，车胎又瘪了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(饮料)无泡的，走了气的","en":"A drink that is flat is no longer fizzy.","ex":{"en":"Could this really stop the champagne from going flat?","cn":"这真的能让香槟不走气吗？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(电池)没电的，电耗光的，电不足的","en":"A flat battery has lost some or all of its electrical charge.","ex":{"en":"His car alarm had been going off for two days and, as a result, the battery was flat.","cn":"他的汽车报警器连着响了两天，结果电池耗没电了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(扁)平足的","en":"If you have flat feet, the arches of your feet are too low.","ex":{"en":"The condition of flat feet runs in families.","cn":"平足会在家族中遗传。"}},{"pos":"ADJ 形容词","cn":"(拒绝或否认)断然的，坚决的","en":"A flat denial or refusal is definite and firm, and is unlikely to be changed.","ex":{"en":"The Foreign Ministry has issued a flat denial of any involvement","cn":"外交部已经坚决否认参与过此事。"}},{"pos":"ADJ 形容词","cn":"飞速的;短短的","en":"If you say that something happened, for example, in ten seconds flat or ten minutes flat, you are emphasizing that it happened surprisingly quickly and only took ten seconds or ten minutes.","ex":{"en":"You're sitting behind an engine that'll move you from 0 to 60mph in six seconds flat","cn":"您面前的引擎，可以在短短 6 秒钟内速度从 0 提升至每小时 60 英里。"}},{"pos":"ADJ 形容词","cn":"(比率、价格或百分比)固定的，统一的","en":"A flat rate, price, or percentage is one that is fixed and which applies in every situation.","ex":{"en":"Fees are charged at a flat rate, rather than on a percentage basis","cn":"费用按固定价格收取，而不是基于百分比收取。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(贸易或商业)停滞的，不景气的","en":"If trade or business is flat, it is slow and inactive, rather than busy and improving or increasing.","ex":{"en":"During the first eight months of this year, sales of big pickups were up 14% while car sales stayed flat","cn":"今年前 8 个月，大型货车的销售量增加了 14％，而小轿车的销售仍然不景气。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"枯燥的;无趣的;乏味的","en":"If you describe something as flat, you mean that it is dull and not exciting or interesting.","ex":{"en":"The past few days have seemed comparatively flat and empty","cn":"过去这几天似乎比较平淡无聊。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(嗓音)平淡的，单调的","en":"You use flat to describe someone's voice when they are saying something without expressing any emotion.","ex":{"en":"'Whatever you say,' he said in a deadly flat voice. 'I'll sit here and wait.'","cn":"“不管你说什么，我都会坐在这里等。”他用一种极为平淡的声音说道。"}},{"pos":"ADJ 形容词","cn":"(用于表示音符的字母后)降半音的，降音的","en":"Flat is used after a letter representing a musical note to show that the note should be played or sung half a tone lower than the note which otherwise matches that letter. Flat is often represented by the symbol after the letter.","ex":{"en":"...Schubert's B flat Piano Trio (Opus 99).","cn":"舒伯特降 B 调钢琴三重奏(第 99 号作品)"}},{"pos":"ADV-GRADED 副词","cn":"(演唱或乐器)比标准音低的，音偏低的","en":"If someone sings flat or if a musical instrument is flat, their singing or the instrument is slightly lower in pitch than it should be.","ex":{"en":"Her vocal range was, to say the least of it, limited, and she had a distressing tendency to sing flat.","cn":"至少可以说，她的音域不够宽，而且令人不舒服的是，她总是音高偏低。"}},{"pos":"PHRASE 短语","cn":"非常平坦的;完全平展的","en":"If you say that something is as flat as a pancake, you are emphasizing that it is completely flat.","ex":{"en":"My home state of Illinois is flat as a pancake","cn":"我的故乡伊利诺伊州一马平川。"}},{"pos":"PHRASE 短语","cn":"摔倒;跌倒","en":"If you fall flat on your face, you fall over.","ex":{"en":"A man walked in off the street and fell flat on his face, unconscious.","cn":"一个男人从街上走进来，趴倒在地，不省人事。"}},{"pos":"PHRASE 短语","cn":"失败;不成功","en":"If an event or attempt falls flat or falls flat on its face, it is unsuccessful.","ex":{"en":"Liz meant it as a joke but it fell flat","cn":"利兹本想开个玩笑，结果却没有达到效果。"}},{"pos":"PHRASE 短语","cn":"一文不名;身无分文;一贫如洗","en":"If you say that you are flat broke, you mean that you have no money at all.","ex":{"en":"Two years later he is flat broke and on the dole.","cn":"两年后，他一贫如洗，靠失业救济金生活。"}},{"pos":"PHRASE 短语","cn":"全速;全力以赴;竭尽全力","en":"If you do something flat out, you do it as fast or as hard as you can.","ex":{"en":"Everyone is working flat out to try to trap those responsible","cn":"每个人都在全力以赴，设法捉住那些罪魁祸首。"}},{"pos":"PHRASE 短语","cn":"完完全全的;确确实实的","en":"You use flat out to emphasize that something is completely the case.","ex":{"en":"That allegation is a flat-out lie","cn":"那项指控是彻头彻尾的谎言。"}},{"pos":"PHRASE 短语","cn":"在平地上","en":"On the flat means on level ground.","ex":{"en":"He had angina and was unable to walk for more than 200 yards on the flat.","cn":"他患有心绞痛，在平地上最多能走 200 码。"}},{"pos":"","cn":"","en":"in a flat spin→see: ;"}]},"examples":[{"en":"It's a 30-year mortgage we just flat out can't handle.","cn":"这是一宗我们根本无法处理的 30 年按揭贷款业务。"},{"en":"Workers are working flat out to meet the rise in demand for new cars.","cn":"为满足对新轿车需求的增加，工人正全力以赴地工作。"}]},"flushes":{"lemma":"flush","media":{"uk":"media/uk/flush__gb_1.mp3","us":"media/us/flush__us_1.mp3"}},"flamboyant":{"media":{"uk":"media/uk/flamboyant__gb_1.mp3","us":"media/us/flamboyant__us_1.mp3"},"oxford":{"phon":"flæmˈbɔɪənt","pos":"adjective","senses":[{"en":"different, confident and exciting in a way that attracts attention","cn":"炫耀的；卖弄的","ex":{"en":"a flamboyant gesture/style/personality","cn":"炫耀的手势／作风／个性"}},{"en":"brightly coloured and likely to attract attention","cn":"艳丽的；绚丽夺目的","ex":{"en":"flamboyant clothes/designs","cn":"艳丽的衣服；华丽的设计"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"引人注目的;炫耀的;时髦的","en":"If you say that someone or something is flamboyant, you mean that they are very noticeable, stylish, and exciting.","ex":{"en":"Freddie Mercury was a flamboyant star of the British hard rock scene.","cn":"弗雷迪·摩克瑞是英国硬摇滚乐界一颗耀眼的明星。"}}]},"examples":[{"en":"a flamboyant gesture/style/personality","cn":"炫耀的手势/作风/个性"},{"en":"flamboyant clothes/designs","cn":"艳丽的衣服；华丽的设计"}]},"fluff":{"media":{"uk":"media/uk/fluff__gb_1.mp3","us":"media/us/fluff__us_1.mp3"},"oxford":{"phon":"flʌf","pos":"noun","senses":[{"en":"small pieces of wool, cotton, etc. that gather on clothes and other surfaces","cn":"（衣服等上的）绒毛，蓬松毛团，尘团","ex":{"en":"This sweater is covered in fluff.","cn":"这件毛衣上覆盖着绒毛。"}},{"en":"soft animal fur or bird feathers, found especially on young animals or birds","cn":"（禽兽，尤指幼者的）绒毛","ex":{"en":"The baby birds were still covered in fluff.","cn":"小鸟身上仍然覆盖着绒毛。"}},{"en":"entertainment that is not serious and is not considered to have great value","cn":"没多大意义的娱乐","lab":"informal, especially North American English，，"},{"en":"to do something badly or to fail at something","cn":"搞糟；弄砸","lab":"informal","ex":{"en":"He completely fluffed an easy shot (= in sport).","cn":"一个唾手可得的进球机会被他搞砸了。"},"pos":"verb"},{"en":"to shake or brush something so that it looks larger and/or softer","cn":"抖松；使松散","ex":{"en":"The female sat on the eggs, fluffing out her feathers.","cn":"雌鸟抖开羽毛孵蛋。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(织物上的)绒毛，蓬松毛团;(小动物的)绒毛","en":"Fluff consists of soft threads or fibres in the form of small, light balls or lumps. For example, you can refer to the fur of a small animal as fluff .","ex":{"en":"...the nestbox which contained two chicks: just small grey balls of fluff","cn":"窝里有两只雏鸟：看上去还只是两个灰色的毛毛球"}},{"pos":"VERB 动词","cn":"出错;搞砸","en":"If you fluff something that you are trying to do, you are unsuccessful or you do it badly.","ex":{"en":"She fluffed her interview at Oxford.","cn":"她在牛津的面试搞砸了。"}},{"pos":"VERB 动词","cn":"抖松(靠垫、羽毛等);使蓬松","en":"If you fluff things such as cushions or feathers, you get a lot of air into them, for example by shaking or brushing them, in order to make them seem larger and lighter.","ex":{"en":"She stood up and fluffed her hair, wiggling her fingers through it and then throwing it back.","cn":"她站起身来，弄松了头发，将手指穿过发丝，然后把头发向后一甩。"}}]},"examples":[{"en":"He completely fluffed an easy shot (= in sport).","cn":"一个唾手可得的进球机会被他搞砸了。"},{"en":"Most actors fluff their lines occasionally.","cn":"多数演员都会偶尔念错台词。"}]},"flour":{"oxford":{"phon":"ˈflaʊə(r)","pos":"noun","senses":[{"en":"a fine white or brown powder made from grain, especially wheat, and used in cooking for making bread, cakes, etc.","cn":"（尤指小麦的）面粉；（谷物磨成的）粉","ex":{"en":"Sift the flour and salt into a bowl.","cn":"把面粉和盐筛入碗中。"}},{"en":"fine soft powder made from the seeds or roots of vegetables","cn":"（种子或蔬菜根茎磨成的）粉，面","ex":{"en":"manioc flour","cn":"木薯粉"}},{"en":"to cover something with a layer of flour","cn":"在…上撒（或覆以）面粉","ex":{"en":"Roll the dough on a lightly floured surface.","cn":"揉生面团时，案板上要撒点面粉。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"面粉","en":"Flour is a white or brown powder that is made by grinding grain. It is used to make bread, cakes, and pastry."},{"pos":"VERB 动词","cn":"给…裹上面粉;在…上撒以面粉","en":"If you flour cooking equipment or food, you cover it with flour.","ex":{"en":"Lightly flour a rolling pin","cn":"在擀面杖上撒上薄薄的一层面粉。"}}]},"media":{"uk":"media/uk/flour__gb_1.mp3","us":"media/us/flour__us_1.mp3"},"examples":[{"en":"Roll the dough on a lightly floured surface.","cn":"揉生面团时，案板上要撒点面粉。"},{"en":"Roll the pastry out on a lightly floured board.","cn":"把面团放在撒有少许面粉的案板上擀平。"}]},"flame":{"oxford":{"phon":"fleɪm","pos":"noun","senses":[{"en":"a hot bright stream of burning gas that comes from something that is on fire","cn":"火焰；火舌","g":"[countable, uncountable]","lab":"British English","ex":{"en":"the tiny yellow flame of a match","cn":"火柴小小的黄色火焰"}},{"en":"a bright red or orange colour","cn":"鲜红色；橘红色；橙黄色","g":"[uncountable]","ex":{"en":"a flame-red car","cn":"橘红色的汽车"}},{"en":"a very strong feeling","cn":"强烈的感情；激情","g":"[countable]","lab":"literary","ex":{"en":"His childhood interest in the game had ignited a flame of passion for football.","cn":"他童年时对足球的兴趣点燃了他对这项运动的激情。"}},{"en":"an angry or offensive message sent to somebody by email or on the internet, typically in quick response to another message","cn":"火药味电邮，激烈的网络言论（尤指对某条信息的回复）","g":"[countable]","lab":"informal"},{"en":"to burn with a bright flame","cn":"燃烧","g":"[intransitive]","lab":"literary","ex":{"en":"The logs flamed on the hearth.","cn":"木柴在壁炉炉床里燃烧。"},"pos":"verb"},{"en":"to become red as a result of a strong emotion; to make something become red","cn":"（因强烈情绪而）变红；使变红","g":"[intransitive, transitive]","lab":"literary","ex":{"en":"Her cheeks flamed with rage.","cn":"她愤怒得两颊通红。"},"pos":"verb"},{"en":"to send somebody an angry or offensive message by email or on the internet","cn":"发送火药味电邮（或互联网信息）","g":"[transitive]","lab":"informal","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"火焰;烈焰;火舌","en":"A flame is a hot bright stream of burning gas that comes from something that is burning.","ex":{"en":"The heat from the flames was so intense that roads melted.","cn":"烈焰的温度很高，连路面都被熔化了。"}},{"pos":"N-COUNT 可数名词","cn":"谩骂性电子邮件;攻击性电子邮件","en":"A flame is an e-mail message which severely criticizes or attacks someone.","ex":{"en":"The best way to respond to a flame is to ignore it.","cn":"回应谩骂性电子邮件的最好办法就是置之不理。"}},{"pos":"VERB 动词","cn":"(因愤怒而脸)变红，发红，涨红","en":"If someone's face flames, it suddenly looks red, usually because they are angry.","ex":{"en":"Her cheeks flamed an angry red","cn":"她气得脸涨红了。"}},{"pos":"N-COUNT 可数名词","cn":"(激情之)火;(怒)火","en":"You can refer to a feeling of passion or anger as a flame of passion or a flame of anger.","ex":{"en":"...that burning flame of love.","cn":"那种熊熊燃烧的爱情之火"}},{"pos":"PHRASE 短语","cn":"突然猛烈燃烧起来;突然失火","en":"If something bursts into flames or bursts into flame, it suddenly starts burning strongly.","ex":{"en":"She managed to scramble out of the vehicle as it burst into flames.","cn":"车子一下子起火了,她设法从里面爬了出来。"}},{"pos":"PHRASE 短语","cn":"煽动…火焰,激化(通常指不良的情绪)","en":"If someone or something fans the flames of a situation or feeling, usually a bad one, they make it more intense or extreme in some way.","ex":{"en":"He accused the Tories of 'fanning the flames of extremism'.","cn":"他谴责保守党分子“煽动极端主义情绪”。"}},{"pos":"PHRASE 短语","cn":"熊熊燃烧;陷入火海;被大火吞没","en":"If something goes up in flames, it starts to burn strongly and is destroyed.","ex":{"en":"Fires broke out everywhere, the entire city went up in flames.","cn":"到处都燃起了火，整个城市陷入一片火海。"}},{"pos":"PHRASE 短语","cn":"起火;失火","en":"Something that is in flames is on fire."}]},"media":{"uk":"media/uk/flame__gb_1.mp3","us":"media/us/flame__us_1.mp3","img":["media/ldoce/img/candle.jpg"]},"examples":[{"en":"The plane burst into flame(s) (= suddenly began burning strongly).","cn":"飞机突然猛烈燃烧起来。"},{"en":"The logs flamed on the hearth.","cn":"木柴在壁炉床里燃烧。"}]},"flexible":{"media":{"uk":"media/uk/flexible__gb_1.mp3","us":"media/us/flexible__us_1.mp3"},"oxford":{"phon":"ˈfleksəbl","pos":"adjective","senses":[{"en":"able to change to suit new conditions or situations","cn":"能适应新情况的；灵活的；可变动的","lab":"approving","ex":{"en":"a more flexible approach","cn":"更灵活的方法"}},{"en":"able to bend easily without breaking","cn":"柔韧的；可弯曲的；有弹性的","ex":{"en":"flexible plastic tubing","cn":"挠性塑料管"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可弯曲的;柔韧的","en":"A flexible object or material can be bent easily without breaking.","ex":{"en":"...brushes with long, flexible bristles.","cn":"鬃毛长而柔韧的毛笔"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易变通的;适应性强的;灵活的","en":"Something or someone that is flexible is able to change easily and adapt to different conditions and circumstances as they occur.","ex":{"en":"Look for software that's flexible enough for a range of abilities.","cn":"寻找功能多、适用性强的软件。"}}]},"examples":[{"en":"Our plans need to be flexible enough to cater for the needs of everyone.","cn":"我们的计划必须能够变通，以满足每个人的需要。"},{"en":"You need to be more flexible and imaginative in your approach.","cn":"你的方法必须更加灵活，更富有想像力。"}]},"flatter":{"oxford":{"phon":"ˈflætə(r)","pos":"verb","senses":[{"en":"to say nice things about somebody, often in a way that is not sincere, because you want them to do something for you or you want to please them","cn":"奉承；讨好；向…谄媚","g":"[transitive]","ex":{"en":"Are you trying to flatter me?","cn":"你是想讨好我？"}},{"en":"to choose to believe something good about yourself and your abilities, especially when other people do not share this opinion","cn":"自命不凡","g":"[transitive]","ex":{"en":"‘How will you manage without me?’ ‘Don't flatter yourself.’","cn":"“没有我看你怎么办！”“别自以为了不起。”"}},{"en":"to make somebody look attractive; to make somebody seem more attractive or better than they really are","cn":"使显得漂亮；使胜过真实水平","g":"[transitive]","ex":{"en":"That colour doesn't flatter many people.","cn":"那种颜色对很多人都不适宜。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"向…谄媚;奉承;讨好","en":"If someone flatters you, they praise you in an exaggerated way that is not sincere, because they want to please you or to persuade you to do something.","ex":{"en":"I knew she was just flattering me.","cn":"我知道她只是在恭维我。"}},{"pos":"VERB 动词","cn":"自认为;自以为是","en":"If you flatter yourself that something good is the case, you believe that it is true, although others may disagree. If someone says to you 'you're flattering yourself' or 'don't flatter yourself', they mean that they disagree with your good opinion of yourself.","ex":{"en":"I flatter myself that this campaign will put an end to the war","cn":"我自认为这次战役将结束这场战争。"}},{"pos":"VERB 动词","cn":"使显得更漂亮","en":"If something flatters you, it makes you appear more attractive.","ex":{"en":"Orange and khaki flatter those with golden skin tones","cn":"橘黄色和卡其色能衬托那些金黄色皮肤的人。"}}]},"media":{"uk":"media/uk/flatter__gb_1.mp3","us":"media/us/flatter__us_1.mp3"},"examples":[{"en":"‘How will you manage without me?’ ‘Don't flatter yourself.’ “","cn":"没有我看你怎么办！” “别自以为了不起。”"},{"en":"The scoreline flattered England (= they did not deserve to get such a high score).","cn":"英格兰队在积分榜上的位置大大超过了其实力。"}]},"flow":{"media":{"uk":"media/uk/flow__gb_1.mp3","us":"media/us/flow__us_1.mp3"},"oxford":{"phon":"fləʊ","pos":"noun","senses":[{"en":"the steady and continuous movement of something/somebody in one direction","cn":"流；流动","sc":"continuous movement","ex":{"en":"the flow of an electric current","cn":"电流的流动"}},{"en":"the continuous production or supply of something","cn":"持续生产；不断供应","sc":"production/supply","ex":{"en":"to encourage the free flow of information","cn":"鼓励信息自由交流"}},{"en":"continuous talk by somebody","cn":"滔滔不绝","sc":"of speech/writing","ex":{"en":"You've interrupted my flow—I can't remember what I was saying.","cn":"你打断了我的话，我记不得我在说什么了。"}},{"en":"the way that words, ideas or themes are linked together in speech, writing or music","cn":"连贯；流畅","sc":"of speech/writing","ex":{"en":"Too many examples can interrupt the smooth flow of the text.","cn":"例子太多会使行文不流畅。"}},{"en":"the movement of the sea towards the land","cn":"涨潮","sc":"of the sea","ex":{"en":"the ebb and flow of the tide","cn":"潮涨潮落"}},{"en":"to move steadily and continuously in one direction","cn":"流；流动","g":"[intransitive]","lab":"figurative","sc":"move continuously","ex":{"en":"She lost control and the tears began to flow.","cn":"她禁不住泪如泉涌。"},"pos":"verb"},{"en":"to move or pass continuously from one place or person to another, especially in large numbers or amounts","cn":"涌流；流动","g":"[intransitive]","sc":"move continuously","ex":{"en":"New orders are finally starting to flow.","cn":"新的订单终于开始纷至沓来。"},"pos":"verb"},{"en":"to develop or be produced in an easy and natural way","cn":"流畅","g":"[intransitive]","sc":"of ideas/conversation","ex":{"en":"Conversation flowed freely throughout the meal.","cn":"席间大家一直相谈甚欢。"},"pos":"verb"},{"en":"to be available easily and in large amounts","cn":"有的是；大量供应","g":"[intransitive]","sc":"be available easily","ex":{"en":"It was obvious that money flowed freely in their family.","cn":"显然他们家族有的是钱。"},"pos":"verb"},{"en":"to be felt strongly by somebody","cn":"被强烈感到","g":"[intransitive]","sc":"of feeling","ex":{"en":"Fear and excitement suddenly flowed over me.","cn":"我突然感到又恐惧又兴奋。"},"pos":"verb"},{"en":"to hang loosely and freely","cn":"飘垂；飘拂","g":"[intransitive]","sc":"of clothes/hair","ex":{"en":"Her hair flowed down over her shoulders.","cn":"她的头发垂到肩上。"},"pos":"verb"},{"en":"to come in towards the land","cn":"涨；涨潮","g":"[intransitive]","sc":"of the sea","ex":{"en":"The sea ebbed and flowed.","cn":"大海时而涨潮时而退潮。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"流动;流向","en":"If a liquid, gas, or electrical current flows somewhere, it moves there steadily and continuously.","ex":{"en":"A stream flowed gently down into the valley","cn":"一条小溪潺潺流进山谷。"}},{"pos":"VERB 动词","cn":"(人群或事物)流动，持续移动","en":"If a number of people or things flow from one place to another, they move there steadily in large groups, usually without stopping.","ex":{"en":"Large numbers of refugees continue to flow from the troubled region into the no-man's land","cn":"大批难民不断从骚乱地区涌入无人地带。"}},{"pos":"VERB 动词","cn":"(信息)传播，流传;(资金)流通","en":"If information or money flows somewhere, it moves freely between people or organizations.","ex":{"en":"A lot of this information flowed through other police departments","cn":"大量此类信息在警察机关其他部门中流传。"}},{"pos":"VERB 动词","cn":"(感情)充满，洋溢","en":"If an emotion flows through someone, they feel it very intensely, often so that other people notice it.","ex":{"en":"In that moment a surge of hatred flowed through my blood","cn":"那一刻，一股仇恨在我的血液中翻涌。"}},{"pos":"VERB 动词","cn":"源自;由…引起","en":"If a quality or situation flows from something, it comes from it or results naturally from it.","ex":{"en":"Undesirable consequences flow from these misconceptions.","cn":"这些误解造成了不良的影响。"}},{"pos":"VERB 动词","cn":"(话语)流畅，流利","en":"If someone's words flow, they are spoken smoothly and continuously.","ex":{"en":"His words flowed more readily.","cn":"他说得更加流利了。"}},{"pos":"VERB 动词","cn":"(头发或衣服)垂下，飘拂","en":"If someone's hair or clothing flows about them, it hangs freely and loosely.","ex":{"en":"...a long white dress which flowed over her body.","cn":"她身上穿的一条飘逸的白色长裙"}},{"pos":"VERB 动词","cn":"充满;满是;到处是","en":"If you say that something flows or that a place flows with it, you are indicating that there is a great deal of that thing in the place.","ex":{"en":"The wine flowed and we danced the night away","cn":"我们喝了很多酒，跳了一个晚上的舞。"}},{"pos":"PHRASE 短语","cn":"滔滔不绝;口若悬河","en":"Someone who is in full flow is talking easily and continuously and seems likely to go on talking for some time.","ex":{"en":"He had been replying for some 40 minutes already and was still in full flow.","cn":"他已经就就此问题回答了 40 分钟左右，仍然不见有停下来的意思。"}},{"pos":"PHRASE 短语","cn":"(活动)如火如荼地进行;(人)全力以赴，充满激情","en":"If you say that an activity, or the person who is performing the activity, is in full flow, you mean that the activity has started and is being carried out with a great deal of energy and enthusiasm.","ex":{"en":"Lunch at Harry's Bar was in full flow when Irene made a splendid entrance","cn":"当艾琳光彩照人地出现在门口时，哈里酒吧的午餐会正是热闹非凡。"}},{"pos":"PHRASE 短语","cn":"随波逐流;随大流","en":"If you go with the flow, you let things happen or let other people tell you what to do, rather than trying to control what happens yourself.","ex":{"en":"There's nothing I can do about the problem, so I might as well go with the flow.","cn":"关于这个问题我无能为力，所以我不如就顺其自然好了。"}}]},"examples":[{"en":"You've interrupted my flow — I can't remember what I was saying.","cn":"你打断了我的话，我记不得我在说什么了。"},{"en":"The party got livelier as the drink began to flow.","cn":"开始尽兴畅饮时，聚会的气氛活跃起来。"}]},"flashes":{"lemma":"flash","media":{"img":["media/pic/creativehobbies_comp.jpg","media/thumb/photography.jpg"],"uk":"media/uk/flash__gb_1.mp3","us":"media/us/flash__us_1.mp3"}},"flagging":{"lemma":"flag","media":{"uk":"media/ldoce/hwd/bre/d/flagging0205.mp3","us":"media/ldoce/hwd/ame/1/laadflagging.mp3"}},"flavoured":{"oxford":{"phon":"ˈfleɪvəd","pos":"adjective","senses":[{"en":"having the type of flavour mentioned","cn":"有…味道的","ex":{"en":"lemon-flavoured sweets/candy","cn":"柠檬味糖果"}},{"en":"having had flavour added to it","cn":"添加了味道的","ex":{"en":"flavoured yogurt","cn":"有添加味道的酸奶"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"添加了调料的","en":"If a food is flavoured, various ingredients have been added to it so that it has a distinctive flavour.","ex":{"en":"...meat flavoured with herbs","cn":"添加了香草的肉"}}]},"media":{"uk":"media/uk/flavoured__gb_1.mp3","us":"media/us/flavoured__us_1.mp3"},"examples":[{"en":"flavoured yogurt","cn":"有添加味道的酸奶"},{"en":"lemon-flavoured sweets/candy","cn":"柠檬味糖果"}],"base":"flavour"},"flags":{"lemma":"flag"},"flattered":{"lemma":"flatter","media":{"uk":"media/ldoce/hwd/bre/f/ld41flattered.mp3","us":"media/ldoce/hwd/ame/f/ld41flattered.mp3"}},"flaws":{"lemma":"flaw"},"fluffy":{"media":{"uk":"media/uk/fluffy__gb_1.mp3","us":"media/us/fluffy__us_1.mp3"},"oxford":{"phon":"ˈflʌfi","pos":"adjective","senses":[{"en":"covered in very soft fur or feathers","cn":"覆有绒毛的；毛茸茸的","ex":{"en":"a little fluffy kitten","cn":"毛茸茸的小猫"}},{"en":"soft, light and containing air","cn":"松软的","ex":{"en":"Beat the butter and sugar until soft and fluffy.","cn":"将黄油和糖搅打松软。"}},{"en":"looking as if it is soft and light","cn":"轻软状的","ex":{"en":"fluffy white clouds","cn":"轻飘飘的白云"}},{"en":"light and not serious; having no substance, depth or power","cn":"轻浮的；空洞的；浅薄的；无说服力的","lab":"informal, disapproving，，","ex":{"en":"a fluffy film/movie","cn":"内容空洞的影片"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"绒毛似的;松软的;蓬松的","en":"If you describe something such as a towel or a toy animal as fluffy, you mean that it is very soft.","ex":{"en":"...fluffy white towels","cn":"柔软的白毛巾"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)松软的","en":"A cake or other food that is fluffy is very light because it has a lot of air in it.","ex":{"en":"Cream together the margarine and sugar with a wooden spoon until light and fluffy.","cn":"用一只木勺把人造黄油和糖搅拌成稀松的糊状。"}}]},"examples":[{"en":"Beat the butter and sugar until soft and fluffy.","cn":"搅打奶油和糖直到松软为止。"},{"en":"a fluffy argument","cn":"一个无说服力的论据"}]},"flames":{"lemma":"flame"},"flaw":{"oxford":{"phon":"flɔː","pos":"noun","senses":[{"en":"a mistake in something that means that it is not correct or does not work correctly","cn":"错误；缺点","ex":{"en":"The argument is full of fundamental flaws.","cn":"这段论述充满根本性的错误。"}},{"en":"a weakness in somebody’s character","cn":"（性格上的）弱点，缺点","ex":{"en":"There is always a flaw in the character of a tragic hero.","cn":"悲剧主角总有性格上的缺点。"}},{"en":"a fault or small break in something that makes it less attractive or valuable","cn":"裂痕；裂隙；瑕疵","ex":{"en":"The vase is in excellent condition except for a few small flaws in its base.","cn":"除了底部有一些小瑕疵外，花瓶状况良好。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"错误;谬误","en":"A flaw in something such as a theory or argument is a mistake in it, which causes it to be less effective or valid.","ex":{"en":"There were, however, a number of crucial flaws in his monetary theory","cn":"但是，他的货币理论中存在若干关键性错误。"}},{"pos":"N-COUNT 可数名词","cn":"（性格中的）缺点，弱点","en":"A flaw in someone's character is an undesirable quality that they have.","ex":{"en":"The only flaw in his character seems to be a short temper.","cn":"他性格中的唯一缺点好像就是脾气急。"}},{"pos":"N-COUNT 可数名词","cn":"瑕疵;缺陷","en":"A flaw in something such as a pattern or material is a fault in it that should not be there."}]},"media":{"uk":"media/uk/flaw__gb_1.mp3","us":"media/us/flaw__us_1.mp3"},"examples":[{"en":"The report reveals fatal flaws in security at the airport.","cn":"报告揭示了机场安全的致命缺陷。"},{"en":"The argument is full of fundamental flaws.","cn":"这段论述充满根本性的错误。"}]},"flesh":{"oxford":{"phon":"fleʃ","pos":"noun","senses":[{"en":"the soft substance between the skin and bones of animal or human bodies","cn":"（动物或人的）肉","g":"[uncountable]","ex":{"en":"The trap had cut deeply into the rabbit's flesh.","cn":"捕夹深深嵌入了兔子的肉里。"}},{"en":"the skin of the human body","cn":"（人体的）皮肤","g":"[uncountable]","ex":{"en":"His fingers closed around the soft flesh of her arm.","cn":"他握住了她柔软的手臂。"}},{"en":"the soft part of fruit and vegetables, especially when it is eaten","cn":"蔬菜的可食部分；果肉","g":"[uncountable]","ex":{"en":"the sweet flesh of a mango","cn":"芒果的甜果肉"}},{"en":"the human body when considering its physical and sexual needs, rather than the mind or soul","cn":"肉体；肉欲；情欲","g":"[singular]","lab":"literary","ex":{"en":"the pleasures/sins of the flesh","cn":"肌肤之乐；肉欲之罪"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"肉","en":"Flesh is the soft part of a person's or animal's body between the bones and the skin.","ex":{"en":"...maggots which eat away dead flesh.","cn":"食腐肉的蛆虫"}},{"pos":"N-UNCOUNT 不可数名词","cn":"肉体;肌肤","en":"You can use flesh to refer to human skin and the human body, especially when you are considering it in a sexual way.","ex":{"en":"...the warmth of her flesh.","cn":"她肌肤的温暖"}},{"pos":"N-UNCOUNT 不可数名词","cn":"果肉;蔬菜的可食部分","en":"The flesh of a fruit or vegetable is the soft inside part of it.","ex":{"en":"Cut the flesh from the olives and discard the stones.","cn":"把橄榄的果肉切下来，然后去除果核。"}},{"pos":"PHRASE 短语","cn":"血肉之躯","en":"You use flesh and blood to emphasize that someone has human feelings or weaknesses, often when contrasting them with machines.","ex":{"en":"I'm only flesh and blood, like anyone else.","cn":"我只是个凡人，和其他人一样。"}},{"pos":"PHRASE 短语","cn":"亲骨肉;至亲","en":"If you say that someone is your own flesh and blood, you are emphasizing that they are a member of your family.","ex":{"en":"The kid, after all, was his own flesh and blood. He deserved a second chance.","cn":"毕竟这个孩子是他的亲骨肉，应该给他第二次机会。"}},{"pos":"PHRASE 短语","cn":"使人反感;使毛骨悚然;使心惊肉跳","en":"If something makes your flesh creep or makes your flesh crawl, it makes you feel disgusted, shocked or frightened.","ex":{"en":"It makes my flesh creep to think of it","cn":"想到它就会让我毛骨悚然。"}},{"pos":"PHRASE 短语","cn":"本人;真身","en":"If you meet or see someone in the flesh, you actually meet or see them, rather than, for example, seeing them in a film or on television.","ex":{"en":"Charles' appeal is best observed in the flesh","cn":"见到查尔斯本人才最能感受到他的魅力。"}},{"pos":"PHRASE 短语","cn":"充实;加细节于;使丰满","en":"If you put flesh on something, you add details and more information to it.","ex":{"en":"This is an attempt to put flesh on what has been a very bare skeleton plan up to now.","cn":"这是一次试图使至今还只是框架的计划充实起来的尝试。"}},{"pos":"","cn":"","en":"pound of flesh→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"加细节于;使丰满;充实","en":"If you flesh out something such as a story or plan, you add details and more information to it.","ex":{"en":"He talked with him for an hour and a half, fleshing out the details of his original five-minute account","cn":"他和他谈了一个半小时，将自己原来5 分钟的陈述完全展开了。"}},{"pos":"","cn":"","en":"相关词组：flesh out"}]},"media":{"uk":"media/uk/flesh__gb_1.mp3","us":"media/us/flesh__us_1.mp3","img":["media/ldoce/img/kiwi.jpg"]},"examples":[{"en":"The strength of the book is that it puts flesh on the bare bones of this argument.","cn":"本书的优点是对这个论点的基本事实有翔实的论述。"},{"en":"These points were fleshed out in the later parts of the speech.","cn":"这几点在演讲的后面部分已得到充实。"}]},"fluency":{"media":{"uk":"media/uk/fluency__gb_1.mp3","us":"media/us/fluency__us_1.mp3"},"oxford":{"phon":"ˈfluːənsi","pos":"noun","senses":[{"en":"the quality of being able to speak or write a language, especially a foreign language, easily and well","cn":"（尤指外语）流利，流畅","ex":{"en":"Fluency in French is required for this job.","cn":"这个工作要求法语熟练自如。"}},{"en":"the quality of doing something in a way that is smooth and shows skill","cn":"熟练自如；流畅","ex":{"en":"The team lacked fluency during the first half.","cn":"该队在上半场打得不够流畅。"}}]},"examples":[{"en":"Fluency in French is required for this job.","cn":"这个工作要求法语熟练自如。"},{"en":"The team lacked fluency during the first half.","cn":"该队在上半场打得不够流畅。"}]},"fleet":{"media":{"uk":"media/uk/fleet__gb_1.mp3","us":"media/us/fleet__us_1.mp3"},"oxford":{"phon":"fliːt","pos":"noun","senses":[{"en":"a group of military ships commanded by the same person","cn":"舰队","g":"[countable]","ex":{"en":"a fleet of destroyers","cn":"驱逐舰舰队"}},{"en":"a group of ships fishing together","cn":"捕鱼船队","g":"[countable]","ex":{"en":"a fishing/whaling fleet","cn":"捕鱼／捕鲸船队"}},{"en":"all the military ships of a particular country","cn":"（一国的）全部军舰，海军","g":"[singular]","ex":{"en":"a reduction in the size of the British fleet","cn":"英国海军规模缩减"}},{"en":"a group of planes, buses, taxis, etc. travelling together or owned by the same organization","cn":"（同一机构或统一调度的）机群，车队","g":"[countable]","ex":{"en":"the company’s new fleet of vans","cn":"公司的新客货车队"}},{"en":"able to run fast","cn":"跑得快的；快速的","ex":{"en":"fleet of foot","cn":"跑得快"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"船队;舰队","en":"A fleet is a group of ships organized to do something together, for example to fight battles or to catch fish.","ex":{"en":"The damage inflicted upon the British fleet was devastating.","cn":"英国舰队遭到了毁灭性的重创。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指同一机构或统一行动的)车队","en":"A fleet of vehicles is a group of them, especially when they all belong to a particular organization or business, or when they are all going somewhere together.","ex":{"en":"With its own fleet of trucks, the company delivers most orders overnight","cn":"这个公司拥有自己的货车车队，大多数订购货品可以隔日送到。"}}]},"examples":[{"en":"the company's new fleet of vans","cn":"公司的新客货车队"},{"en":"a reduction in the size of the British fleet","cn":"英国海军的裁减"}]},"flush":{"media":{"uk":"media/uk/flush__gb_1.mp3","us":"media/us/flush__us_1.mp3"},"oxford":{"phon":"flʌʃ","pos":"verb","senses":[{"en":"to become red, especially because you are embarrassed, angry or hot; to make somebody's face become red","cn":"（使）发红，脸红","g":"[intransitive, transitive]","ex":{"en":"She flushed with anger.","cn":"她气得涨红了脸。"}},{"en":"when a toilet flushes or you flush it, water passes through it to clean it, after a handle, etc. has been pressed","cn":"冲（抽水马桶）","g":"[intransitive, transitive]"},{"en":"to clean something by causing water to pass through it","cn":"（用水）冲洗干净，冲洗","g":"[transitive]","ex":{"en":"Flush the pipe out with clean water.","cn":"用净水冲洗管子。"}},{"en":"to get rid of something with a sudden flow of water or other liquid","cn":"（用水或其他液体）冲走","g":"[transitive]","ex":{"en":"They flushed the drugs down the toilet.","cn":"他们从马桶冲走了毒品。"}},{"en":"to force a person or an animal to leave the place where they are hiding","cn":"把（人或动物从藏身处）驱赶出来","g":"[transitive]","ex":{"en":"They're trying to flush him out of hiding.","cn":"他们正试图把他从藏身处赶出来。"}},{"en":"a red colour that appears on your face or body because you are embarrassed, excited or hot","cn":"脸红；潮红","g":"[countable, usually singular]","ex":{"en":"A pink flush spread over his cheeks.","cn":"他满脸通红。"},"pos":"noun"},{"en":"a sudden strong feeling; the hot feeling on your face or body caused by this","cn":"一阵强烈情感；（流露出的）一阵激情","g":"[countable, usually singular]","ex":{"en":"a flush of anger/embarrassment/enthusiasm/guilt","cn":"一阵愤怒／尴尬／热情／内疚"},"pos":"noun"},{"en":"the act of cleaning a toilet with a sudden flow of water","cn":"冲（抽水马桶）","g":"[singular]","ex":{"en":"Give the toilet a flush.","cn":"冲抽水马桶。"},"pos":"noun"},{"en":"a set of cards that a player has that are all of the same suit","cn":"同花的一手牌","g":"[countable]","pos":"noun"},{"en":"having a lot of money, usually for a short time","cn":"富有，很有钱（通常为短期的）","lab":"informal","ex":{"en":"I’m flush this week—I’ll pay.","cn":"这周我很红——我会付钱的。"},"pos":"adjective"},{"en":"completely level with each other","cn":"完全齐平","ex":{"en":"Make sure the paving stones are flush with the lawn.","cn":"务必要使铺路石和草坪齐平。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"脸红;(脸)发烫，发红","en":"If you flush, your face goes red because you are hot or ill, or because you are feeling a strong emotion such as embarrassment or anger.","ex":{"en":"Do you sweat a lot or flush a lot?","cn":"你常出汗或是脸上常发烫吗？"}},{"pos":"V-ERG 及物/不及物动词","cn":"(便后)冲(马桶)","en":"When someone flushes a toilet after using it, they fill the toilet bowl with water in order to clean it, usually by pressing a handle or pulling a chain. You can also say that a toilet flushes .","ex":{"en":"She flushed the toilet and went back in the bedroom.","cn":"她冲完马桶回到卧室。"}},{"pos":"VERB 动词","cn":"把…冲下(抽水马桶)","en":"If you flush something down the toilet, you get rid of it by putting it into the toilet bowl and flushing the toilet.","ex":{"en":"He was found trying to flush banknotes down the toilet.","cn":"他试图把钞票从马桶里冲走时被发现。"}},{"pos":"VERB 动词","cn":"冲洗(身体部位)","en":"If you flush a part of your body, you clean it or make it healthier by using a large amount of liquid to get rid of dirt or harmful substances.","ex":{"en":"Flush the eye with clean cold water for at least 15 minutes","cn":"用干净冷水冲洗眼睛至少 15 分钟。"}},{"pos":"VERB 动词","cn":"(用大量液体)冲洗","en":"If you flush dirt or a harmful substance out of a place, you get rid of it by using a large amount of liquid.","ex":{"en":"That won't flush out all the sewage, but it should unclog some stinking drains.","cn":"那样做虽不能将污物全部冲掉，但应该能疏通一些散发恶臭的排水管。"}},{"pos":"VERB 动词","cn":"把(人或动物)驱出;把…赶出","en":"If you flush people or animals out of a place where they are hiding, you find or capture them by forcing them to come out of that place.","ex":{"en":"They flushed them out of their hiding places","cn":"他们把他们从藏身之处赶了出来。"}},{"pos":"ADJ 形容词","cn":"齐平的;在同一平面的","en":"If one object or surface is flush with another, they are at the same height or distance from something else, so that they form a single smooth surface.","ex":{"en":"Make sure the tile is flush with the surrounding tiles.","cn":"要保证每块瓷砖都和它周围的瓷砖在同一平面上。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(通常指短时间内)有钱的，富足的;暴富的","en":"If you are flush with money, you have a lot of it, usually only for a short time.","ex":{"en":"At that time, many developing countries were flush with dollars earned from exports","cn":"在那时，许多发展中国家都通过出口赚到了大量美元。"}},{"pos":"N-SING 单数名词","cn":"一阵强烈感情;一阵兴奋(或快乐)","en":"The flush of something is an intense feeling of excitement or pleasure that you have when you are experiencing it and for a short time afterwards.","ex":{"en":"...the first flush of young love.","cn":"年轻人初尝恋爱滋味的兴奋"}},{"pos":"N-SING 单数名词","cn":"激增;大量涌出","en":"A flush of something is a large quantity of it that comes suddenly or quickly.","ex":{"en":"...the flush of recent victories.","cn":"最近接二连三的胜利"}},{"pos":"","cn":"","en":"相关词组：flush out"}]},"examples":[{"en":"in the first flush of youth/enthusiasm/romance","cn":"在青春活力旺盛时期；在热情高涨阶段；在热恋的初期"},{"en":"Drinking lots of water will help to flush toxins out of the body.","cn":"大量饮水有助于清除体内毒素。"}]},"floors":{"lemma":"floor"},"flannels":{"lemma":"flannel"},"fleeing":{"lemma":"flee"},"flocks":{"oxford":{"phon":"flɒk","pos":"noun","senses":[{"en":"a group of sheep, goats or birds of the same type （","cn":"羊或鸟）群"},{"en":"a large group of people, especially of the same type （","cn":"尤指同类人的）一大群"}]}},"floods":{"lemma":"flood"},"flattening":{"oxford":{"phon":"ˈflætn","pos":"verb","senses":[{"en":"to become or make sth become flat or flatter （","cn":"使）变平；把 … 弄平"},{"en":"to destroy or knock down a building, tree, etc.","cn":"摧毁，推倒，弄倒（建筑物、树木等）"}]}},"flicks":{"lemma":"flick"},"floorboards":{"lemma":"floorboard"},"flats":{"lemma":"flat"},"flights":{"lemma":"flight"},"flashed":{"lemma":"flash"},"flagstones":{"oxford":{"phon":"ˈflæɡstəʊn","pos":"noun","senses":[{"en":"a large flat square piece of stone that is used for floors, paths, etc.","cn":"石板（方形，用于铺地面、小径等）"}]}},"floats":{"lemma":"float"},"flourishing":{"lemma":"flourish"},"flowers":{"lemma":"flower"},"flourished":{"lemma":"flourish"},"flowing":{"lemma":"flow","media":{"uk":"media/ldoce/hwd/bre/d/flowing0205.mp3","us":"media/ldoce/hwd/ame/3/flowing.mp3"}},"flare":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"闪光信号灯;照明弹","en":"A flare is a small device that produces a bright flame. Flares are used as signals, for example on ships.","ex":{"en":"...a ship which had fired a distress flare.","cn":"发出遇险信号弹的一艘船"}},{"pos":"VERB 动词","cn":"(火)突然烧旺，突然熊熊燃烧","en":"If a fire flares, the flames suddenly become larger.","ex":{"en":"Camp fires flared like beacons in the dark.","cn":"营火突然熊熊燃烧起来，看上去就像黑暗中的航标灯。"}},{"pos":"VERB 动词","cn":"(麻烦、暴乱、冲突等)加剧，升级，愈演愈烈","en":"If something such as trouble, violence, or conflict flares, it starts or becomes more violent.","ex":{"en":"Even as the President appealed for calm, trouble flared in several American cities.","cn":"尽管总统呼吁保持冷静，美国一些城市的骚乱仍有所升级。"}},{"pos":"VERB 动词","cn":"发怒;发火","en":"If people's tempers flare, they get angry.","ex":{"en":"Tempers flared and harsh words were exchanged.","cn":"怒气突然爆发，人们开始恶言相向。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(常因气愤或难过而)张大(鼻孔),(鼻孔)张开","en":"If someone's nostrils flare or if they flare them, their nostrils become wider, often because the person is angry or upset.","ex":{"en":"I turned to Jacky, my nostrils flaring in disgust","cn":"我转过身厌恶地看着杰基，鼻翼呼呼地翕动着。"}},{"pos":"VERB 动词","cn":"(连衣裙等)底部展开，呈喇叭形展开","en":"If something such as a dress flares, it spreads outwards at one end to form a wide shape.","ex":{"en":"...a simple black dress, cut to flare from the hips.","cn":"一条简洁的黑裙，剪裁成从胯部向外展开的式样"}},{"pos":"N-PLURAL 复数名词","cn":"喇叭裤","en":"Flares are trousers that are very wide at the bottom."},{"pos":"PHRASAL VERB 短语动词","cn":"(疾病、伤势)突然复发，突然恶化","en":"If a disease or injury flares up, it suddenly returns or becomes painful again.","ex":{"en":"Students often find that their acne flares up before and during exams.","cn":"学生们经常发现在考前和考试期间他们的粉刺会严重起来。"}},{"pos":"","cn":"","en":"相关词组：flare up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to start burning accidentally","cn":""},{"en":"to suddenly start burning and produce a lot of flames that cause serious damage","cn":""},{"en":"if a building or vehicle goes up or goes up in flames , it starts burning very quickly and usually is destroyed by fire","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 n 4 n","senses":[{"en":"A flare is a sudden burst of light. The flare of a lit match in the dark night is strangely beautiful."}]},"collocations":{"phrases":["ADV. suddenly Anger suddenly flared in his eyes. | briefly A light flared briefly, then went out. | up Violence flared up in the capital las","PHRASES flare into life The fire flared into life again."]},"media":{"uk":"media/ldoce/hwd/bre/b/flair0205.mp3","us":"media/ldoce/hwd/ame/7/flair.mp3"},"examples":[{"en":"The ship sent up distress flares to attract the attention of the coastguard.","cn":"这艘船点起了遇险信号以引起海岸警卫队的注意。"},{"en":"‘You should have told me!’ she flared at him. “","cn":"你应该告诉我的！”她气冲冲地对他说。"}],"oxford":{"phon":"fleə(r)","pos":"verb","senses":[{"en":"to burn brightly, but usually for only a short time or not steadily","cn":"（短暂）烧旺；（摇曳着）燃烧；（火光）闪耀","g":"[intransitive]","lab":"figurative","ex":{"en":"The match flared and went out.","cn":"火柴闪亮了一下就熄了。"}},{"en":"to suddenly start or become much stronger","cn":"突发；加剧","g":"[intransitive]","ex":{"en":"Violence flared when the police moved in.","cn":"警察逼近时爆发了暴力行为。"}},{"en":"to say something in an angry and aggressive way","cn":"发怒地说；粗暴地说","g":"[transitive, intransitive]","ex":{"en":"‘You should have told me!’ she flared at him.","cn":"“你应该告诉我的！”她气冲冲地对他说。"}},{"en":"to become wider towards the bottom","cn":"底部展开；呈喇叭形","g":"[intransitive]","ex":{"en":"The sleeves are tight to the elbow, then flare out.","cn":"袖子在肘部收紧，接着逐渐展开。"}},{"en":"if a person or an animal flares their nostrils (= the openings at the end of the nose), or if their nostrils flare, they become wider, especially as a sign of anger","cn":"（尤指因气愤）使（鼻孔）张开，（鼻孔）张开","g":"[transitive, intransitive]","ex":{"en":"The horse backed away, its nostrils flaring with fear.","cn":"马向后惊退，吓得鼻翼扇动。"}},{"en":"a bright but unsteady light or flame that does not last long","cn":"（短暂的）旺火；（摇曳的）光；（闪耀的）火光","g":"[countable, usually singular]","ex":{"en":"The flare of the match lit up his face.","cn":"火柴的光照亮了他的脸。"},"pos":"noun"},{"en":"a device that produces a bright flame, used especially as a signal; a flame produced in this way","cn":"闪光装置；闪光信号灯；照明弹","g":"[countable]","ex":{"en":"The ship sent up distress flares to attract the attention of the coastguard.","cn":"这艘船发出了遇险信号以引起海岸警卫队的注意。"},"pos":"noun"},{"en":"a shape that becomes gradually wider","cn":"逐渐展开；喇叭形","g":"[countable]","ex":{"en":"a skirt with a slight flare","cn":"下摆略张的裙子"},"pos":"noun"},{"en":"trousers that become very wide at the bottom of the legs","cn":"喇叭裤","g":"[plural]","lab":"British English also","ex":{"en":"a pair of flares","cn":"一条喇叭裤"},"pos":"noun"},{"en":"a period during which a medical condition returns for a time","cn":"（疾病的）复发","g":"[countable]","ex":{"en":"Some soap products may trigger eczema flares.","cn":"有些肥皂产品会引起湿疹复发。"},"pos":"noun"}]}},"flourish":{"collins":{"senses":[{"pos":"VERB 动词","cn":"繁荣;兴盛;兴旺","en":"If something flourishes, it is successful, active, or common, and developing quickly and strongly.","ex":{"en":"Business flourished and within six months they were earning 18,000 roubles a day","cn":"生意红火起来，不出6 个月他们就可以每天赚 18,000 卢布了。"}},{"pos":"VERB 动词","cn":"(植物或动物)长势好，茁壮成长","en":"If a plant or animal flourishes, it grows well or is healthy because the conditions are right for it.","ex":{"en":"The plant flourishes particularly well in slightly harsher climes.","cn":"这种植物在气候条件稍差一点的地区长势尤其好。"}},{"pos":"VERB 动词","cn":"挥动，挥舞(以引起注意)","en":"If you flourish an object, you wave it about in a way that makes people notice it.","ex":{"en":"He flourished the glass to emphasize the point.","cn":"他挥动手中的杯子来强调这一点。"}},{"pos":"N-COUNT 可数名词","cn":"(为引人注意的)夸张动作","en":"If you do something with a flourish, you do in a showy way so that people notice it.","ex":{"en":"She tended to finish dancing with a flourish.","cn":"她往往以夸张的姿势结束舞蹈。"}},{"pos":"N-COUNT 可数名词","cn":"装饰曲线;装饰图案","en":"A flourish is a curly line or piece of decoration.","ex":{"en":"He scrawled his name across the bill, underlining it with a showy flourish.","cn":"他在账单上潦草地签上自己的名字，并在名字下面画了一条花体线。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to show someone or something that you are proud of to other people","cn":""},{"en":"to let people see your valuable possessions so that they know you are rich or successful, in a way that annoys people","cn":""},{"en":"to wave something in your hand in order to make people notice it 〔","cn":"为引起注意而〕挥动〔手中的东西〕"}]},"vocab":{"pos":"1 v 2 n v 3 n","senses":[{"en":"A flourish is an extra touch — a trumpet's \"ta-ta-da!\" announcing a king's entrance, a fancy carving atop an otherwise utilitarian pillar, a wave of a flag or a cheerleader's pompom."}]},"collocations":{"phrases":["ADJ. final | dramatic, rhetorical, theatrical a speech full of rhetorical flourishes","VERB + FLOURISH end in/with, finish with | start (off) with | sign with Bill signed on the bottom line with a flourish.","PREP. with a ~ With a final flourish she laid down her pen.","PHRASES a flourish of trumpets"]},"media":{"uk":"media/ldoce/hwd/bre/b/flourish_v0205.mp3","us":"media/ldoce/hwd/ame/1/laadflourish_.mp3"},"examples":[{"en":"The season ended with a flourish for Rooney, when he scored in the final minute of the match.","cn":"鲁尼本赛季华丽收关：他在比赛最后一分钟射进一球。"},{"en":"Few businesses are flourishing in the present economic climate.","cn":"在目前的经济气候下，很少有企业兴旺发达。"}],"oxford":{"phon":"ˈflʌrɪʃ","pos":"verb","senses":[{"en":"to develop quickly and become successful or common","cn":"繁荣；昌盛；兴旺","g":"[intransitive]","ex":{"en":"Few businesses are flourishing in the present economic climate.","cn":"在目前的经济气候下，很少有企业兴旺发达。"}},{"en":"to grow well; to be healthy and happy","cn":"茁壮成长；健康幸福","g":"[intransitive]","lab":"especially British English","ex":{"en":"These plants flourish in a damp climate.","cn":"这些植物在潮湿的气候下长势茂盛。"}},{"en":"to wave something around in a way that makes people look at it","cn":"（为引起注意）挥舞","g":"[transitive]","ex":{"en":"He rushed into the room flourishing the newspaper.","cn":"他拿着报纸冲进房间。"}},{"en":"an exaggerated movement that you make when you want somebody to notice you","cn":"（为引起注意的）夸张动作","g":"[usually singular]","ex":{"en":"He opened the door for her with a flourish.","cn":"他做了一个夸张的动作为她开门。"},"pos":"noun"},{"en":"an impressive act or way of doing something","cn":"给人深刻印象的行动；令人难忘的方式","g":"[usually singular]","ex":{"en":"The season ended with a flourish for Kane, when he scored in the final minute of the match.","cn":"凯恩本赛季华丽收官：他在比赛最后一分钟射进一球。"},"pos":"noun"},{"en":"a detail or decoration that is used in speech or writing","cn":"（讲话或文章的）华丽辞藻，修饰","ex":{"en":"a speech full of rhetorical flourishes","cn":"满篇华丽辞藻的演讲"},"pos":"noun"},{"en":"a curved line that is used as decoration, especially in writing","cn":"（尤指手写体的）装饰曲线，花饰","ex":{"en":"Her signature was a complicated affair of practised flourishes.","cn":"她的签名是一种复杂的、熟练的花语。"},"pos":"noun"},{"en":"a loud short piece of music that is usually played to announce an important person or event","cn":"花彩号声","g":"[usually singular]","ex":{"en":"a flourish of trumpets","cn":"小号齐鸣"},"pos":"noun"}]}},"flank":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胁;胁腹","en":"An animal's flank is its side, between the ribs and the hip.","ex":{"en":"He put his hand on the dog's flank.","cn":"他把手放在狗的胁腹上。"}},{"pos":"N-COUNT 可数名词","cn":"(军队的)侧翼，翼侧","en":"A flank of an army or navy force is one side of it when it is organized for battle.","ex":{"en":"The assault element, led by Captain Ramirez, opened up from their right flank.","cn":"拉米雷斯上尉率领的突击队从他们的右翼开火。"}},{"pos":"N-COUNT 可数名词","cn":"(大型物体的)侧面，一侧，一边","en":"The side of anything large can be referred to as its flank .","ex":{"en":"They continued along the flank of the mountain.","cn":"他们沿着山的一侧继续前行。"}},{"pos":"VERB 动词","cn":"两侧有;(有时指)一侧有","en":"If something is flanked by things, it has them on both sides of it, or sometimes on one side of it.","ex":{"en":"The altar was flanked by two Christmas trees","cn":"圣坛两侧是两棵圣诞树。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the side of an animal’s or person’s body, between the rib s and the hip","cn":"胁部﹐胁腹"},{"en":"the side of an army in a battle, or a sports team when playing 〔","cn":"军队或球队的〕侧翼"},{"en":"the side of a hill, mountain, or very large building 〔","cn":"山或大型建筑物的〕侧面"}]},"vocab":{"pos":"n v","senses":[{"en":"A flank is the side of something, whether of beef or a military formation."}]},"collocations":{"phrases":["ADJ. left, right | north, northern, etc. | lower the lower flanks of Vesuvius | mountain","VERB + FLANK attack They decided to attack their enemy's southern flank. | defend, protect | expose West Ham exposed the right flank of Norw","FLANK + NOUN attack","PREP. along a/the ~ along the eastern flank of Greenland | down the ~ a beautiful pass down the right flank | on a/the ~ The army was attack"]},"media":{"uk":"media/ldoce/hwd/bre/a/flank_n0205.mp3","us":"media/ldoce/hwd/ame/0/flank1.mp3"},"examples":[{"en":"They drove through the cotton fields that flanked Highway 17.","cn":"他们驾车穿过了 17 号公路侧面的棉田。"},{"en":"She left the courtroom flanked by armed guards.","cn":"她在武装警卫护送下离开法庭。"}],"oxford":{"phon":"flæŋk","pos":"noun","senses":[{"en":"the side of something such as a building or mountain","cn":"（建筑物、山等的）侧面","ex":{"en":"The sun lit up the western flank of the hill.","cn":"太阳照亮了山的西侧。"}},{"en":"the left or right side of an army during a battle, or a sports team during a game","cn":"（军队或运动队的）翼侧，侧面，侧翼","ex":{"en":"Our orders were to attack their left flank.","cn":"我们的命令是攻击他们的左翼。"}},{"en":"the side of an animal between the ribs and the hip","cn":"（动物的）胁腹","ex":{"en":"She patted the horse’s flank.","cn":"她拍拍马腹。"}},{"en":"to have somebody/something on one or both sides","cn":"侧面（或两侧）有","ex":{"en":"She left the courtroom flanked by armed guards.","cn":"她在武装警卫护送下离开法庭。"},"pos":"verb"},{"en":"to be placed on one or both sides of something","cn":"位于…的侧翼；在…侧面","ex":{"en":"They drove through the cotton fields that flanked Highway 17.","cn":"他们驾车穿过了 17 号公路边上的棉田。"},"pos":"verb"}]}},"flavouring":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"调味品;调料","en":"Flavourings are substances that are added to food or drink to give it a particular taste.","ex":{"en":"Our range of herbal teas contain no preservatives, colourings or artificial flavourings.","cn":"我们这一系列的药草茶不含防腐剂、色素以及人工调味品。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance used to give something a particular flavour or increase its flavour","cn":"调味品﹐调味香料"}]},"collocations":{"phrases":["ADJ. artificial, natural This product contains only natural flavourings. | food | peppermint, vanilla, etc.","QUANT. drop Add a few drops of peppermint flavouring.","VERB + FLAVOURING contain | use We don't use any artificial flavourings in our products. | add"]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeflavouring.mp3","us":"media/ldoce/hwd/ame/1/amelasdeflavouring.mp3"},"examples":[{"en":"This food contains no artificial flavourings.","cn":"这种食品不含人工调味品。"},{"en":"orange/vanilla flavouring","cn":"橙/香草调味香料"}],"oxford":{"phon":"ˈfleɪvərɪŋ","pos":"noun","senses":[{"en":"a substance added to food or drink to give it a particular taste","cn":"调味品；调味香料","ex":{"en":"orange/vanilla flavouring","cn":"橙／香草调味香料"}}]},"base":"flavour"},"flex":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(电器用)花线，皮线","en":"A flex is an electric cable containing two or more wires that is connected to an electrical appliance."},{"pos":"VERB 动词","cn":"活动，屈伸(肌肉或身体某一部分)","en":"If you flex your muscles or parts of your body, you bend, move, or stretch them for a short time in order to exercise them.","ex":{"en":"He slowly flexed his muscles and tried to stand.","cn":"他缓慢地活动了一下肌肉，想尽量站起来。"}},{"pos":"","cn":"","en":"to flex your muscles→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tighten your muscles or bend part of your body","cn":"收紧〔肌肉〕﹔屈曲〔身体部位〕"},{"en":"to show your ability to do something, especially your skill or power","cn":"展示自己的才能〔尤指技艺或力量〕"},{"en":"an electrical wire covered with plastic, used to connect electrical equipment to an electricity supply 〔","cn":"电器用〕花线﹐皮线"}]},"collocations":{"phrases":["ADJ. long | trailing Long trailing flexes are a serious trip hazard. | electric/electical | kettle, telephone, etc.","QUANT. length","VERB + FLEX cut Side cutters are useful for cutting electrical flex to length."]},"media":{"uk":"media/ldoce/hwd/bre/c/flex_v0205.mp3","us":"media/ldoce/hwd/ame/c/flex.mp3","img":["media/thumb/flex.jpg"]},"examples":[{"en":"He stood on the side of the pool flexing his muscles.","cn":"他站在游泳池旁活动肌肉。"},{"en":"to flex your fingers/feet/legs","cn":"活动手指/双脚/双腿"}],"oxford":{"phon":"fleks","pos":"verb","senses":[{"en":"to bend, move or stretch an arm or a leg, or pull a muscle tight, especially in order to prepare for a physical activity","cn":"屈伸，活动（四肢或肌肉，尤指为准备体力活动）","ex":{"en":"to flex your fingers/feet/legs","cn":"活动手指／双脚／双腿"}},{"en":"a piece of wire that is covered with plastic, used for carrying electricity to a piece of equipment","cn":"花线；皮线","ex":{"en":"an electric flex","cn":"一根导电花线"},"pos":"noun"}]}},"floorboard":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a board in a wooden floor","cn":"一块木地板"},{"en":"the floor in a car 〔","cn":"汽车的〕底板"}]},"collocations":{"phrases":["ADJ. wooden | bare | polished | loose | creaking, squeaky","VERB + FLOORBOARD lay The builders are still laying the floorboards. | lift (up) Lift some loose floorboards to get at the pipes.","FLOORBOARD + VERB creak The wooden floorboards creaked as he walked down the corridor.","PREP. beneath/under/underneath the ~ They said that he kept his money under the floorboards.","PHRASES a gap between/in the floorboards She could hear voices through the gaps in the floorboards."]},"media":{"uk":"media/ldoce/hwd/bre/e/floorboard0205.mp3","us":"media/ldoce/hwd/ame/5/floorboard.mp3"},"examples":[{"en":"He had his foot to the floorboard (= was going very fast).","cn":"他猛踩油门飞速驾驶。"},{"en":"bare/polished floorboards","cn":"素面/打了蜡的地板"}],"oxford":{"phon":"ˈflɔːbɔːd","pos":"noun","senses":[{"en":"a long flat piece of wood in a wooden floor","cn":"木质地板条；木板条","ex":{"en":"bare/polished floorboards","cn":"素面／打了蜡的木地板"}},{"en":"the bottom surface of a vehicle","cn":"（车辆的）地板","g":"[usually singular]","lab":"North American English","ex":{"en":"a car floorboard","cn":"汽车地板"}}]}},"flicker":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(灯光等)闪烁，摇曳","en":"If a light or flame flickers, it shines unsteadily.","ex":{"en":"Fluorescent lights flickered, and then the room was brilliantly, blindingly bright","cn":"荧光灯闪了几下，接着屋子里豁然大亮，刺得人睁不开眼。"}},{"pos":"N-COUNT 可数名词","cn":"(情感的)闪现，一闪而过","en":"If you experience a flicker of emotion, you feel that emotion only for a very short time, and not very strongly.","ex":{"en":"He felt a flicker of regret","cn":"他突然感到一丝悔意。"}},{"pos":"VERB 动词","cn":"(表情)掠过，闪过","en":"If an expression flickers across your face, it appears very briefly.","ex":{"en":"A smile flickered across Vincent's grey features.","cn":"文森特苍白的面孔上掠过一丝微笑。"}},{"pos":"VERB 动词","cn":"(眼睛)瞟过","en":"If someone's eyes flicker towards something, they look at it quickly.","ex":{"en":"Dirk's eyes flickered towards the pistol","cn":"德克的眼睛瞟向那把手枪。"}},{"pos":"VERB 动词","cn":"抖动;颤动","en":"If something flickers, it makes very slight, quick movements.","ex":{"en":"In a moment her eyelids flickered, then opened","cn":"她的眼皮随即动了一下，然后睁开了眼睛。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to produce bright light","cn":""},{"en":"to shine brightly for a very short time, or to shine on and off very quickly many times","cn":""},{"en":"to shine with a very strong light which hurts your eyes","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 n","senses":[{"en":"To flicker is to flash on and off at random. If your computer screen is flickering right now, you are probably having trouble reading this."}]},"collocations":{"phrases":["ADJ. faint, slight, small, tiny She caught the faintest flicker of amusement on his face. | brief, momentary | last (often figurative) The s","VERB + FLICKER give The candle gave one last flicker and went out. | show | catch, notice, see | detect, feel She felt a brief flicker of je","FLICKER + VERB cross sth A flicker of guilt crossed his face. | catch your eye A flicker of movement caught her eye and she turned her head.","PREP. with a ~ of &lsquo;He'll soon be here,&rsquo; she thought, with a flicker of excitement. | without a ~ of She spoke without any flicke","PHRASES the flicker of a candle/flame The brief flicker of a candle flame caught our eyes. | the flicker of an eyelid, a flicker of sb's/the"]},"media":{"uk":"media/ldoce/hwd/bre/6/flicker_v0205.mp3","us":"media/ldoce/hwd/ame/5/flicker1.mp3"},"examples":[{"en":"Her eyelids flickered as she slept.","cn":"她睡觉时眼睑不停地眨动。"},{"en":"the flickering screen of the television","cn":"图像在抖动的电视荧光屏"}],"oxford":{"phon":"ˈflɪkə(r)","pos":"verb","senses":[{"en":"to keep going on and off as it shines or burns","cn":"闪烁；闪现；忽隐忽现；摇曳","g":"[intransitive]","ex":{"en":"The lights flickered and went out.","cn":"灯光闪了闪就熄了。"}},{"en":"to be expressed or appear somewhere for a short time","cn":"闪现；一闪而过","g":"[intransitive]","ex":{"en":"Anger flickered in his eyes.","cn":"他眼中闪现出一股怒火。"}},{"en":"to move with small quick movements","cn":"快速摆动；颤动；抖动；拍动","g":"[intransitive]","ex":{"en":"Her eyelids flickered as she slept.","cn":"她睡觉时眼睑不停地抖动。"}},{"en":"a light that shines in an unsteady way","cn":"（光）摇曳，闪烁，忽隐忽现","ex":{"en":"the flicker of a television/candle","cn":"电视画面的闪动；烛光的摇曳"},"pos":"noun"},{"en":"a small, sudden movement with part of the body","cn":"（身体部位的）小而快的动作","ex":{"en":"the flicker of an eyelid","cn":"眼睑的跳动"},"pos":"noun"},{"en":"a feeling or an emotion that lasts for only a very short time","cn":"（情感、情绪的）闪现，一闪而过","ex":{"en":"a flicker of hope/doubt/interest","cn":"希望／怀疑／兴趣的闪现"},"pos":"noun"}]}},"flee":{"collins":{"senses":[{"pos":"VERB 动词","cn":"逃离;逃避","en":"If you flee from something or someone, or flee a person or thing, you escape from them.","ex":{"en":"He slammed the bedroom door behind him and fled","cn":"他把卧室房门重重地关上，然后逃跑了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to leave a place when someone is trying to catch you or stop you, or when there is a dangerous situation","cn":""},{"en":"to escape from someone who is chasing you, especially when there is no chance that you will be caught. Get away is more informal than escape","cn":""},{"en":"to escape from someone who is holding you","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you bolt, scram, skedaddle, or get the heck of out Dodge, you flee . You run away fast. Don’t confuse flee with \"flea.\" They sound alike, but the second kind is an insect whose bites make you itch."}]},"collocations":{"phrases":["ADV. abroad, across the border, into exile Hundreds of refugees fled across the border to escape the fighting. | north, south, etc. | in pan","VERB + FLEE be forced to, have to They were forced to flee the country. | try to | manage to | turn They turned and fled when they saw the g","PREP. from She dropped the phone and fled from the office. | into/to They fled to Britain when the war started.","PHRASES flee empty-handed When the police arrived the burglars fled empty-handed. | flee for your life She had to flee for her life when sol"]},"media":{"uk":"media/ldoce/hwd/bre/0/flee0205.mp3","us":"media/ldoce/hwd/ame/4/flea.mp3"},"examples":[{"en":"He fled to London after an argument with his family.","cn":"他与家人争吵以后离家去了伦敦。"},{"en":"He was caught trying to flee the country.","cn":"他企图逃离该国时被抓住了。"}],"oxford":{"phon":"fliː","pos":"verb","senses":[{"en":"to leave a person or place very quickly, especially because you are afraid of possible danger","cn":"迅速离开；（尤指害怕有危险而）逃避，逃跑","ex":{"en":"She burst into tears and fled.","cn":"她突然哭了起来，跑开了。"}}]}},"flashback":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(电影、小说、戏剧中的)闪回，倒叙","en":"In a film, novel, or play, a flashback is a scene that returns to events in the past.","ex":{"en":"There is even a flashback to the murder itself.","cn":"甚至有一段关于谋杀本身的闪回。"}},{"pos":"N-COUNT 可数名词","cn":"(往事的)突然重现，闪回，再现","en":"If you have a flashback to a past experience, you have a sudden and very clear memory of it.","ex":{"en":"He has recurring flashbacks to the night his friends died.","cn":"他反复想起朋友们死去的那个夜晚的情形。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a scene in a film, play, book etc that shows something that happened before that point in the story 〔","cn":"电影的〕闪回镜头﹔〔戏剧的〕闪回场景﹔〔书中的〕倒叙"},{"en":"a sudden very clear memory of something that happened to you in the past 〔","cn":"往事的〕闪回﹐突然重现"},{"en":"an occasion when someone has the same bad feeling that they had when they took an illegal drug in the past 〔","cn":"在未吸毒时产生的〕药效幻觉重现"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A flashback is a transition in a story to an earlier time, that interrupts the normal chronological order of events. A flashback in a movie might show what happened when a character was younger."}]},"collocations":{"phrases":["ADJ. sudden","VERB + FLASHBACK get, have","PREP. in (a) ~ The story is told in flashback. | ~ to I had a sudden flashback to the time immediately after the war."]},"media":{"uk":"media/ldoce/hwd/bre/c/flashback0205.mp3","us":"media/ldoce/hwd/ame/a/flashback.mp3"},"examples":[{"en":"The events that led up to the murder were shown in a series of flashbacks.","cn":"通过一系列倒叙展现出了导致谋杀的各个情节。"},{"en":"The reader is told the story in flashback.","cn":"故事是以倒叙手法向读者讲述的。"}],"oxford":{"phon":"ˈflæʃbæk","pos":"noun","senses":[{"en":"a part of a film, play, etc. that shows a scene that happened earlier in time than the main story","cn":"（电影或戏剧的）闪回，倒叙，倒叙片段","g":"[countable, uncountable]","ex":{"en":"The events that led up to the murder were shown in a series of flashbacks.","cn":"通过一系列倒叙展现出了导致谋杀的各个情节。"}},{"en":"a sudden, very clear, strong memory of something that happened in the past that is so real you feel that you are living through the experience again","cn":"（往事的）闪回，回顾","g":"[countable]","ex":{"en":"war veterans suffering from nightmares and flashbacks","cn":"饱受噩梦和闪回之苦的退伍军人"}}]}},"flair":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"天资;天赋;天分","en":"If you have a flair for a particular thing, you have a natural ability to do it well.","ex":{"en":"...a friend who has a flair for languages.","cn":"有语言天赋的朋友"}},{"pos":"N-UNCOUNT 不可数名词","cn":"才华;资质;创意","en":"If you have flair, you do things in an original, interesting, and stylish way.","ex":{"en":"Their work has all the usual punch, panache and flair you'd expect.","cn":"他们的作品一如既往地引人入胜、气韵潇洒、新颖别致，不会让你失望。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an ability to do something well, especially because you have learned and practised it","cn":""},{"en":"a natural ability to do something well which can be developed with practice","cn":""},{"en":"very great ability, which only a few people have","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Use the word flair to refer to someone’s knack or natural talent for something. Someone might have a flair for throwing fantastic parties, or a flair for solving complex math problems."}]},"collocations":{"phrases":["ADJ. considerable, great | real | natural | artistic, creative, design, entrepreneurial, imaginative","VERB + FLAIR have She has a natural flair for languages. | show | lack His designs are all right, but he lacks artistic flair. | develop","PREP. with ~ jazz guitarists who improvise with flair | ~ for an activist with a flair for publicity"]},"media":{"uk":"media/ldoce/hwd/bre/b/flair0205.mp3","us":"media/ldoce/hwd/ame/7/flair.mp3"},"examples":[{"en":"He has a flair for languages.","cn":"他有学语言的天分。"},{"en":"She dresses with real flair.","cn":"她衣着甚有品味。"}],"oxford":{"phon":"fleə(r)","pos":"noun","senses":[{"en":"a natural ability to do something well","cn":"天分；天资；天赋","g":"[singular, uncountable]","ex":{"en":"He has a flair for languages.","cn":"他有学语言的天分。"}},{"en":"a quality showing the ability to do things in an interesting way that shows imagination","cn":"才华；资质","g":"[uncountable]","ex":{"en":"artistic flair","cn":"艺术魅力"}}]}},"flick":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"轻弹;轻击;轻快地移动","en":"If something flicks in a particular direction, or if someone flicks it, it moves with a short, sudden movement.","ex":{"en":"His tongue flicked across his lips","cn":"他的舌头迅速舔了一下嘴唇。"}},{"pos":"VERB 动词","cn":"轻弹;轻拭","en":"If you flick something away, or off something else, you remove it with a quick movement of your hand or finger.","ex":{"en":"Shirley flicked a speck of fluff from the sleeve of her black suit","cn":"雪莉弹掉了黑色套装袖子上的一点小绒毛。"}},{"pos":"VERB 动词","cn":"抽打;挥动","en":"If you flick something such as a whip or a towel, or flick something with it, you hold one end of it and move your hand quickly up and then forward, so that the other end moves.","ex":{"en":"He helped her up before flicking the reins","cn":"他帮她上马，之后挥动了缰绳。"}},{"pos":"VERB 动词","cn":"(快速地)按(开关等)","en":"If you flick a switch, or flick an electrical appliance on or off, you press the switch sharply so that it moves into a different position and works the equipment.","ex":{"en":"He flicked a light-switch on the wall beside the door","cn":"他啪的一声打开了门边墙上的电灯开关。"}},{"pos":"VERB 动词","cn":"快速翻阅;浏览;不停地转换(电视频道)","en":"If you flick through a book or magazine, you turn its pages quickly, for example to get a general idea of its contents or to look for a particular item. If you flick through television channels, you continually change channels very quickly, for example using a remote control.","ex":{"en":"She was flicking through some magazines on a table","cn":"她正翻看着桌上的几本杂志。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something small and light go forward through the air with a quick movement of your thumb and finger","cn":""},{"en":"to make something move away by hitting or pushing it suddenly or quickly, especially with your thumb and finger 〔","cn":"尤指用大拇指和另一手指〕弹﹐拂"},{"en":"to move with a sudden quick movement, or to make something move in this way","cn":"晃动﹐拍动﹔抖掉"}]},"vocab":{"pos":"1 v n 2 v 3 v 4 n","senses":[{"en":"A flick is a quick, short movement, usually coming from the wrist or hand. There used to be a \" Flick a Bic \" cigarette ad: cigarettes are awful, but starting a lighter is a classic flick ."}]},"collocations":{"phrases":["ADV. casually | nervously | quickly | away, back","PREP. across His tongue flicked nervously across dry lips. | from He casually flicked away some dust from his jacket. | off She flicked the ","PHRASES flick sth open She snatched up her briefcase and flicked it open. PHRASAL VERBS flick through sth","ADV. absent-mindedly, casually, idly She flicked idly through a magazine. | quickly"]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdeflick.mp3","us":"media/ldoce/hwd/ame/8/flick1.mp3"},"examples":[{"en":"I've only had time to flick through your report but it seems to be fine.","cn":"我的时间不多，只是草草翻阅了一下你的报告，但似乎还不错。"},{"en":"Flicking through the channels, I came across an old war movie.","cn":"我快速浏览电视频道，发现有一部老的战争片在播放。"}],"oxford":{"phon":"flɪk","pos":"verb","senses":[{"en":"to hit something lightly with a sudden quick movement, especially using your finger and thumb together, or your hand","cn":"（尤指用手指或手快速地）轻击，轻拍，轻拂，轻弹","g":"[transitive]","ex":{"en":"She flicked the dust off her collar.","cn":"她轻轻弹掉了衣领上的灰尘。"}},{"en":"to move or make something move with sudden quick movements","cn":"（使）突然快速移动","g":"[intransitive, transitive]","ex":{"en":"The snake's tongue flicked out.","cn":"蛇吐着芯子。"}},{"en":"to smile or look at somebody suddenly and quickly","cn":"向…笑了一下（或瞥了一眼等）","g":"[transitive]","ex":{"en":"She flicked a nervous glance at him.","cn":"她紧张不安地瞟了他一眼。"}},{"en":"to press a button or switch quickly in order to turn a machine, etc. on or off","cn":"（快速地）按（开关），按（键）","g":"[transitive]","ex":{"en":"He flicked a switch and all the lights went out.","cn":"他啪的一声按了下开关，灯全熄了。"}},{"en":"to move something up and down with a sudden movement so that the end of it hits somebody/something","cn":"（用…）轻挥，轻打","g":"[transitive]","ex":{"en":"He flicked me with a wet towel.","cn":"他用湿毛巾轻打我。"}},{"en":"to move your finger quickly across the screen of an electronic device such as a mobile phone or small computer in order to move text, pictures, etc.","cn":"（用手指在手机等电子装置屏幕上）快速滑动，快速滑屏","g":"[intransitive, transitive]","ex":{"en":"Flick to the next photo and pinch to zoom in or out.","cn":"滑屏至下一张照片，然后两指开合将照片放大或缩小。"}},{"en":"a small sudden, quick movement or hit, for example with a whip or part of the body","cn":"（用鞭子等的）轻打；（身体部位的）小而快的动作","g":"[countable, usually singular]","ex":{"en":"Bell's flick into the penalty area helped to create the goal.","cn":"贝尔迅速插进禁区助攻，创造了这次进球的机会。"},"pos":"noun"},{"en":"a quick look through a book, magazine, website, etc.","cn":"快速浏览；草草翻阅","g":"[singular]","lab":"especially British English","ex":{"en":"I had a flick through the catalogue while I was waiting.","cn":"我等待时浏览了目录。"},"pos":"noun"},{"en":"a film","cn":"电影","g":"[countable]","lab":"old-fashioned, informal，，","pos":"noun"},{"en":"the cinema","cn":"电影院","g":"[plural]","lab":"old-fashioned, British English, informal，，，，","pos":"noun"}]}},"flop":{"collins":{"senses":[{"pos":"VERB 动词","cn":"猛然坐下;重重地坐下","en":"If you flop into a chair, for example, you sit down suddenly and heavily because you are so tired.","ex":{"en":"Bunbury flopped down upon the bed and rested his tired feet","cn":"邦伯里重重地倒在了床上，让他疲惫的双脚休息一下。"}},{"pos":"VERB 动词","cn":"凌乱地垂下;猛落下","en":"If something flops onto something else, it falls there heavily or untidily.","ex":{"en":"The briefcase flopped onto the desk","cn":"公文包重重地落在桌上。"}},{"pos":"N-COUNT 可数名词","cn":"彻底失败;惨败","en":"If something is a flop, it is completely unsuccessful.","ex":{"en":"It is the public who decide whether a film is a hit or a flop.","cn":"决定一部电影会走红还是惨败的是大众。"}},{"pos":"VERB 动词","cn":"彻底失败;惨败","en":"If something flops, it is completely unsuccessful.","ex":{"en":"The film flopped badly at the box office.","cn":"这部电影票房惨淡。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be completely unsuccessful, in a way that makes people feel disappointed and embarrassed","cn":""},{"en":"if an event, especially a social event, is a disaster , it makes people feel angry, disappointed, or embarrassed, instead of being enjoyable","cn":""},{"en":"if a situation or event is a shambles , it is completely unsuccessful because it has been very badly planned or organized","cn":""}]},"collocations":{"phrases":["ADJ. almighty, big, resounding, spectacular The show was the biggest flop in TV history. | complete | expensive The concert may prove an exp"]},"media":{"uk":"media/ldoce/hwd/bre/c/flop_las3_br.mp3","us":"media/ldoce/hwd/ame/9/flop1.mp3"},"examples":[{"en":"Exhausted, he flopped down into a chair.","cn":"他筋疲力尽，一屁股坐到椅子上。"},{"en":"Her hair flopped over her eyes.","cn":"她的头发耷拉下来遮住了眼睛。"}],"oxford":{"phon":"flɒp","pos":"verb","senses":[{"en":"to sit or lie down in a heavy and sudden way because you are very tired","cn":"（因疲惫而）猛然坐下，沉重地躺下","g":"[intransitive]","ex":{"en":"Exhausted, he flopped down into a chair.","cn":"他筋疲力尽，一屁股坐到椅子上。"}},{"en":"to fall, move or hang in a heavy way, without control","cn":"（沉重、不受控制地）落下，移动，悬挂","g":"[intransitive]","ex":{"en":"Her hair flopped over her eyes.","cn":"她的头发耷拉下来遮住了眼睛。"}},{"en":"to be a complete failure","cn":"砸锅；完全失败","g":"[intransitive]","lab":"informal","ex":{"en":"The play flopped on Broadway.","cn":"这出戏在百老汇砸了锅。"}},{"en":"a thing or person that is not successful, especially a film, show or party","cn":"（尤指电影、表演、聚会等）失败，不成功","ex":{"en":"a box-office flop","cn":"不卖座"},"pos":"noun"}]}},"flout":{"collins":{"senses":[{"pos":"VERB 动词","cn":"无视，藐视，轻视(法律等)","en":"If you flout something such as a law, an order, or an accepted way of behaving, you deliberately do not obey it or follow it.","ex":{"en":"...illegal campers who persist in flouting the law","cn":"一向对法律熟视无睹的非法露营者"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not obey a person, order, rule, or law","cn":""},{"en":"to not obey a law or rule","cn":""},{"en":"to deliberately refuse to obey a rule or law, or what someone in authority tells you to do","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To flout is to scorn or show contempt for. \"I flout the law and the concept of civilian safety by making a concerted effort to jaywalk every time I cross a street.\""}]},"collocations":{"phrases":["ADV. deliberately, openly The protesters have openly flouted the law."]},"media":{"uk":"media/ldoce/hwd/bre/d/flout_las3_br.mp3","us":"media/ldoce/hwd/ame/4/flout.mp3"},"examples":[{"en":"Motorists regularly flout the law.","cn":"驾车者经常无视法律。"},{"en":"to flout authority/convention","cn":"公然藐视权威/惯例"}],"oxford":{"phon":"flaʊt","pos":"verb","senses":[{"en":"to show that you have no respect for a law, etc. by openly not obeying it","cn":"公然藐视，无视（法律等）","ex":{"en":"Motorists regularly flout the law.","cn":"驾车者经常无视法律。"}}]}},"flattery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"奉承;阿谀;恭维","en":"Flattery consists of flattering words or behaviour.","ex":{"en":"He is ambitious and susceptible to flattery.","cn":"他雄心勃勃，而且很喜欢听别人的恭维话。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things you say to someone to show that you admire them or approve of what they have done","cn":""},{"en":"what you say when you tell someone they look nice or they have done something well","cn":""},{"en":"nice things that you say about someone, which may not be true, in order to get something that you want from them","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Flattery is excessive praise. If you're hoping to borrow your brother's car, be careful not to overdo it when you compliment his haircut, new shoes, and singing voice — he knows flattery when he sees it."}]},"collocations":{"phrases":["ADJ. artificial","VERB + FLATTERY use Salespeople are often accused of using artificial flattery. | fall for She falls for his flattery every time.","PREP. through ~ He thinks he can get his way through flattery. | with ~ She persuaded him with flattery."]},"media":{"uk":"media/ldoce/hwd/bre/e/flattery0205.mp3","us":"media/ldoce/hwd/ame/7/flattery.mp3"},"examples":[{"en":"You're too intelligent to fall for his flattery.","cn":"你很聪明，不会受他的阿谀奉承所惑。"}],"oxford":{"phon":"ˈflætəri","pos":"noun","senses":[{"en":"praise that is not sincere, especially in order to obtain something from somebody","cn":"奉承；阿谀；讨好；恭维","ex":{"en":"You're too intelligent to fall for his flattery.","cn":"你很聪明，不会受他的阿谀奉承所惑。"}}]}},"flail":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(四肢)拼命乱动,使劲乱摆","en":"If your arms or legs flail or if you flail them about, they wave about in an energetic but uncontrolled way.","ex":{"en":"His arms were flailing in all directions","cn":"他的手臂胡乱挥舞着。"}},{"pos":"N-COUNT 可数名词","cn":"连枷(脱粒用的农具)","en":"A flail is a tool which consists of a piece of wood or metal that can swing freely from a handle. Flails are used to beat crops such as corn in order to separate the grain from the rest of the plant."},{"pos":"","cn":"","en":"相关词组：flail around"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to wave your arms or legs in an uncontrolled way","cn":"手脚乱动﹔胡乱地挥[踢]"},{"en":"to beat someone or something violently, usually with a stick 〔","cn":"用棍子〕敲打﹐殴打"},{"en":"to beat grain with a flail","cn":"用连枷打（谷）"}]},"vocab":{"pos":"n v","senses":[{"en":"To flail means to wave around wildly. If you are stranded on a deserted island and you see a ship in the distance, it’s a good idea to flail your arms in the air to get the captain’s attention."}]},"collocations":{"phrases":["ADV. desperately, helplessly, wildly She ran along, her arms flailing wildly. | about, around He flailed about in the water, shouting &lsquo"]},"media":{"uk":"media/ldoce/hwd/bre/d/flail_v0205.mp3","us":"media/ldoce/hwd/ame/9/flail1.mp3"},"examples":[{"en":"The boys flailed around on the floor.","cn":"男孩子们在地板上任意地动来动去。"},{"en":"He was running along, his arms flailing wildly.","cn":"他向前跑，拼命摆动双臂。"}],"oxford":{"phon":"fleɪl","pos":"verb","senses":[{"en":"to move around without control; to move your arms and legs around without control","cn":"乱动；胡乱摆动","g":"[intransitive, transitive]","ex":{"en":"The boys flailed around on the floor.","cn":"男孩子们在地板上手舞足蹈任意地动来动去。"}},{"en":"to hit somebody/something very hard, especially with a stick","cn":"（尤指用棍棒）猛击，猛打","g":"[transitive]"},{"en":"a tool that has a long handle with a short stick hanging from it, used especially in the past to separate grains of wheat from their dry outer layer, by beating the wheat","cn":"连枷（旧时长柄脱粒农具）","pos":"noun"}]}},"flammable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易燃的;可燃的","en":"Flammable chemicals, gases, cloth, or other things catch fire and burn easily.","ex":{"en":"...flammable liquids such as petrol or paraffin.","cn":"汽油和煤油之类的易燃液体"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be able to be burned","cn":""},{"en":"materials, chemicals, or gases that are flammable or inflammable will start burning very easily and quickly, so they can be dangerous","cn":""},{"en":"something that is flammable burns easily","cn":"易燃的"}]},"vocab":{"pos":"adj","senses":[{"en":"Don't smoke when you're getting gas at the gas station! Gasoline is flammable , as is dry grass, old wood, cloth and mattresses."}]},"collocations":{"phrases":["VERBS be","ADV. highly These materials are highly flammable."]},"media":{"uk":"media/ldoce/hwd/bre/e/flammable0205.mp3","us":"media/ldoce/hwd/ame/9/flammable.mp3"},"examples":[{"en":"highly flammable liquids","cn":"高度易燃的液体"},{"en":"Caution! Highly flammable liquid.","cn":"小心！高度易燃液体。"}],"oxford":{"phon":"ˈflæməbl","pos":"adjective","senses":[{"en":"that can burn easily","cn":"易燃的；可燃的","ex":{"en":"highly flammable liquids","cn":"高度易燃的液体"}}]}},"flask":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(可随身携带饮料的)瓶子","en":"A flask is a bottle which you use for carrying drinks around with you.","ex":{"en":"He took out a metal flask from a canvas bag.","cn":"他从帆布包里拿出一个金属瓶子。"}},{"pos":"N-COUNT 可数名词","cn":"烧瓶;长颈瓶","en":"A flask is a bottle or other container which is used in science laboratories and industry for holding liquids.","ex":{"en":"...flasks for the transport of spent fuel.","cn":"用来运送废弃燃料的瓶子"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special type of bottle that you use to keep liquids either hot or cold, for example when travelling","cn":"保温瓶，保温杯"},{"en":"a hip flask","cn":"扁酒瓶"},{"en":"a glass bottle with a narrow top, used in a laboratory 〔","cn":"实验室用的〕烧瓶"}]},"collocations":{"phrases":["ADJ. Thermos(R), vacuum | hip | metal, silver | conical, culture, round bottom (all science)","VERB + FLASK fill | carry When he climbed in the snow he always carried a silver flask of brandy for emergencies. | pull out She pulled out ","FLASK + VERB contain sth a culture flask containing 4ml of the medium","PREP. ~ of We took a flask of tea with us."]},"media":{"img":["media/ldoce/img/thermos.jpg"],"uk":"media/ldoce/hwd/bre/2/flask0205.mp3","us":"media/ldoce/hwd/ame/6/flask.mp3"},"examples":[{"en":"a flask of tea/coffee","cn":"一保温瓶的茶/咖啡"}],"oxford":{"phon":"flɑːsk","pos":"noun","senses":[{"en":"a bottle with a narrow top, used in scientific work for mixing or storing chemicals","cn":"烧瓶","ex":{"en":"a culture flask containing 4 ml of the medium","cn":"装有 4 毫升培养基的培养瓶"}},{"en":"a container like a bottle with double walls with a vacuum between them, used for keeping liquids hot or cold","cn":"真空瓶；保温瓶；热水瓶；冰瓶","lab":"British English","ex":{"en":"a flask of tea/coffee","cn":"一保温瓶的茶／咖啡"}},{"en":"a small flat bottle made of metal or glass and often covered with leather, used for carrying alcohol with you","cn":"小扁酒瓶（用金属或玻璃制成，常带皮套，随身携带）","lab":"especially North American English","ex":{"en":"He had a flask of Scotch in his pocket.","cn":"他的口袋里装着一瓶苏格兰威士忌。"}}]}},"flog":{"collins":{"senses":[{"pos":"VERB 动词","cn":"出售;卖掉","en":"If someone tries to flog something, they try to sell it.","ex":{"en":"They are trying to flog their house.","cn":"他们正试图卖掉房子。"}},{"pos":"VERB 动词","cn":"鞭笞;棒打","en":"If someone is flogged, they are hit very hard with a whip or stick as a punishment.","ex":{"en":"In these places people starved, were flogged, were clubbed to death","cn":"在这些地方，人们忍饥挨饿，遭受鞭打，甚至会被乱棍打死。"}},{"pos":"PHRASE 短语","cn":"做徒劳无益的事;白忙活","en":"If you say that someone is flogging a dead horse, you mean that they are trying to achieve something impossible."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give something to someone in exchange for money","cn":""},{"en":"to send goods to another country to be sold","cn":""},{"en":"to buy and sell a particular type of goods as part of your business","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To flog is to beat or hit, especially with a tool like a stick or rod. A cruel trainer might flog an unruly horse with a whip."}]},"collocations":{"phrases":["ADV. publicly Offenders were publicly flogged.","PHRASES flog sb to death"]},"media":{"uk":"media/ldoce/hwd/bre/2/flog0205.mp3","us":"media/ldoce/hwd/ame/f/flog.mp3"},"examples":[{"en":"He was publicly flogged for breaking the country's alcohol laws.","cn":"他因违犯国家的酒法而被当众处以鞭刑。"},{"en":"I had a letter from a company trying to flog me insurance.","cn":"我收到了一家公司的信，向我推销保险。"}],"oxford":{"phon":"flɒɡ","pos":"verb","senses":[{"en":"to punish somebody by hitting them many times with a whip or stick","cn":"鞭笞，棒打（作为惩罚）","g":"[often passive]","ex":{"en":"He was publicly flogged for breaking the country's alcohol laws.","cn":"他因违犯国家的酒法而被当众处以鞭刑。"}},{"en":"to sell something to somebody","cn":"出售（某物给某人）","lab":"British English, informal，，","ex":{"en":"She flogged her guitar to another student.","cn":"她把吉他卖给另一个同学。"}}]}},"flinch":{"collins":{"senses":[{"pos":"VERB 动词","cn":"退缩;畏缩","en":"If you flinch, you make a small sudden movement, especially when something surprises you or hurts you.","ex":{"en":"Murat had looked into the eyes of the firing squad without flinching","cn":"穆拉特毫不退缩地直视着执行枪决的行刑队员们的眼睛。"}},{"pos":"VERB 动词","cn":"躲避;回避;不愿意做","en":"If you flinch from something unpleasant, you are unwilling to do it or think about it, or you avoid doing it.","ex":{"en":"The world community should not flinch in the face of this challenge","cn":"国际社会在面对这一挑战时不应该回避。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move your face or body away from someone or something because you are in pain, frightened, or upset 〔","cn":"因疼痛﹑害怕﹑生气而〕退缩﹐畏缩"},{"en":"to feel embarrassed or upset","cn":"尴尬﹔生气"},{"en":"to be willing to do something even though it is difficult or unpleasant","cn":"不回避（做）某事"}]},"vocab":{"pos":"v n","senses":[{"en":"To flinch is to react to pain by wincing, pulling away, or cringing. Often it's used to describe a person who shows a moment of weakness or fright: he was so tough, I thought he'd never flinch , but snakes really freak him out."}]},"collocations":{"phrases":["ADV. violently | almost | hardly He hardly flinched when he was hit. | slightly | visibly | inwardly She flinched inwardly as he took her ha","VERB + FLINCH make sb Her finger touched the scar on his forehead, making him flinch.","PREP. at She flinched visibly at the sight of the body. | from She flinched away from him. (figurative) She won't flinch from speaking her m"]},"media":{"uk":"media/ldoce/hwd/bre/c/flinch0205.mp3","us":"media/ldoce/hwd/ame/4/flinch.mp3"},"examples":[{"en":"He never flinched from facing up to trouble.","cn":"他敢于面对困难，从不退缩。"},{"en":"He met my gaze without flinching.","cn":"他毫不畏缩，跟我对视着。"}],"oxford":{"phon":"flɪntʃ","pos":"verb","senses":[{"en":"to make a sudden movement with your face or body as a result of pain, fear, surprise, etc.","cn":"（突然）退缩；畏缩","ex":{"en":"He met my gaze without flinching.","cn":"他毫不畏缩，跟我对视着。"}}]}},"fling":{"collins":{"senses":[{"pos":"VERB 动词","cn":"猛掷;用力抛","en":"If you fling something somewhere, you throw it there using a lot of force.","ex":{"en":"The woman flung the cup at him","cn":"那个女人使劲把杯子朝他扔去。"}},{"pos":"VERB 动词","cn":"突然冲向;突然跳向","en":"If you fling yourself somewhere, you move or jump there suddenly and with a lot of force.","ex":{"en":"He flung himself to the floor.","cn":"他突然跳到地板上。"}},{"pos":"VERB 动词","cn":"急伸，猛动(尤指头或手臂)","en":"If you fling a part of your body in a particular direction, especially your arms or head, you move it there suddenly.","ex":{"en":"She flung her arms around my neck and kissed me.","cn":"她突然张开手臂搂住我的脖子，然后吻了我一下。"}},{"pos":"VERB 动词","cn":"把…摔倒","en":"If you fling someone to the ground, you push them very roughly so that they fall over.","ex":{"en":"The youth got him by the front of his shirt and flung him to the ground.","cn":"年轻人抓住他的衬衫前襟，把他摔在了地上。"}},{"pos":"VERB 动词","cn":"扔;摔;丢","en":"If you fling something into a particular place or position, you put it there in a quick or angry way.","ex":{"en":"Peter flung his shoes into the corner","cn":"彼得把他的鞋子甩到角落里。"}},{"pos":"VERB 动词","cn":"投身于;致力于","en":"If you fling yourself into a particular activity, you do it with a lot of enthusiasm and energy.","ex":{"en":"She flung herself into her career","cn":"她一心扑在事业上。"}},{"pos":"N-COUNT 可数名词","cn":"风流韵事","en":"If two people have a fling, they have a brief sexual relationship.","ex":{"en":"She claims she had a brief fling with him 30 years ago.","cn":"她声称在 30 年前曾和他有过一段短暂的风流韵事。"}},{"pos":"N-SING 单数名词","cn":"短暂的放纵;一时的尽情享乐","en":"A fling is a short period of enjoyment, especially the last one that you will get an opportunity to have.","ex":{"en":"...that last fling before you finally give up and take up a job.","cn":"你最终收心并开始工作之前的最后一次放纵"}},{"pos":"","cn":"(在许多短语中可代替 throw）","en":"Fling can be used instead of 'throw' in many expressions that usually contain 'throw'."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something such as a ball or stone move quickly through the air using your hand","cn":""},{"en":"to throw something, especially in a careless way without using much effort","cn":""},{"en":"to throw something with a lot of force","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 n","senses":[{"en":"To fling is to throw something with force. You'll start a food fight in the cafeteria if you fling your vegetables at the kid across the table."}]},"collocations":{"phrases":["ADJ. brief | (one) final, (one) last The athlete will have one final fling (= participate in one final competition) before retirement.","VERB + FLING have She's had her fling and now she's got to settle down.","PREP. ~ with He had a fling with his neighbour's wife."]},"media":{"uk":"media/ldoce/hwd/bre/7/fling_v0205.mp3","us":"media/ldoce/hwd/ame/d/fling1.mp3"},"examples":[{"en":"He was determined to have one last fling before retiring.","cn":"他决心在退休前最后来一次痛痛快快的玩乐。"},{"en":"He flung out an arm to stop her from falling.","cn":"他猛伸手臂扶她，她才没有跌倒。"}],"oxford":{"phon":"flɪŋ","pos":"verb","senses":[{"en":"to throw or push somebody/something with force, especially because you are angry, or in a careless way","cn":"（尤指生气或随意地）扔，掷，丢，推","lab":"especially British English","ex":{"en":"Someone had flung a brick through the window.","cn":"有人把一块砖扔进了窗户。"}},{"en":"to move yourself or part of your body suddenly and with a lot of force","cn":"猛动（身体或身体部位）","ex":{"en":"She flung herself onto the bed.","cn":"她扑倒在床上。"}},{"en":"to say something to somebody in an aggressive way","cn":"粗暴地（向某人）说；气势汹汹地（对某人）说","ex":{"en":"They were flinging insults at each other.","cn":"他们互相辱骂。"}},{"en":"a short period of fun when you do not allow yourself to worry or think seriously about anything","cn":"一阵尽情欢乐；一时的放纵","ex":{"en":"He was determined to have one last fling before retiring.","cn":"他决心在退休前最后痛痛快快地玩乐一番。"},"pos":"noun"},{"en":"a short sexual relationship with somebody","cn":"短暂的风流韵事","ex":{"en":"We had a brief fling, but it’s over now.","cn":"我们有过一段短暂的风流韵事，但现在已经结束了。"},"pos":"noun"}]}},"flea":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蚤;跳蚤","en":"A flea is a very small jumping insect that has no wings and feeds on the blood of humans or animals."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small insect without wings that jumps and bites animals and people to eat their blood","cn":"跳蚤"},{"en":"to talk angrily to someone, especially because they have done something you disapprove of 〔","cn":"尤指因某人做了你不赞成的事而〕一顿臭骂轰走某人"}]},"collocations":{"phrases":["ADJ. cat, dog, etc.","VERB + FLEA get, have | be riddled with | control This drug is given to dogs to control fleas.","FLEA + VERB jump | bite | carry/spread disease","FLEA + NOUN bite | collar, powder"]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdeflea.mp3","us":"media/ldoce/hwd/ame/4/flea.mp3","img":["media/thumb/flea.jpg"]},"examples":[{"en":"The dog has fleas.","cn":"这条狗有跳蚤。"},{"en":"Are you sure the dog has fleas ?","cn":"你确定那只狗身上有跳蚤吗？"}],"oxford":{"phon":"fliː","pos":"noun","senses":[{"en":"a very small jumping insect without wings, that bites animals and humans and drinks their blood","cn":"蚤","ex":{"en":"The dog has fleas.","cn":"这条狗有跳蚤。"}}]}},"fluctuate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"变动;波动;上下浮动","en":"If something fluctuates, it changes a lot in an irregular way.","ex":{"en":"Body temperature can fluctuate if you are ill.","cn":"人患病后体温可能会上下波动。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change often","cn":""},{"en":"if something varies , it changes according to what the situation is","cn":""},{"en":"if something such as a price or amount fluctuates , it changes very often from a high level to a low one and back again","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Something that fluctuates varies or changes — it's the opposite of steady. Like the ups and downs of the stock market or the relationship status of a Hollywood starlet."}]},"collocations":{"phrases":["ADV. considerably | sharply, widely, wildly Prices have fluctuated wildly in recent years. | constantly, continually constantly fluctuating ","PREP. according to Traffic congestion fluctuates according to the time of day. | around The number of boys at the school fluctuates around 1"]},"media":{"uk":"media/ldoce/hwd/bre/1/fluctuate0205.mp3","us":"media/ldoce/hwd/ame/a/fluctuate.mp3"},"examples":[{"en":"During the crisis, oil prices fluctuated between $20 and $40 a barrel.","cn":"在危机时期，每桶石油价格在 20 元至 40 元之间波动。"},{"en":"Temperatures can fluctuate by as much as 10 degrees.","cn":"温差可达 10 度之多。"}],"oxford":{"phon":"ˈflʌktʃueɪt","pos":"verb","senses":[{"en":"to change frequently in size, amount, quality, etc., especially from one extreme to another","cn":"（大小、数量、质量等）波动；（在…之间）起伏不定","ex":{"en":"fluctuating prices","cn":"波动的价格"}}]}},"flannel":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"法兰绒","en":"Flannel is a soft cloth, usually made of cotton or wool, that is used for making clothes.","ex":{"en":"He wore a faded red flannel shirt.","cn":"他身穿一件褪了色的红色法兰绒衬衫。"}},{"pos":"N-PLURAL 复数名词","cn":"法兰绒男裤","en":"Flannels are men's trousers made of flannel.","ex":{"en":"...respectable young chaps, dressed in flannels and blazers.","cn":"穿着法兰绒裤子和夹克的体面小伙子们"}},{"pos":"N-COUNT 可数名词","cn":"(洗澡用的)毛巾","en":"A flannel is a small cloth that you use for washing yourself."},{"pos":"N-UNCOUNT 不可数名词","cn":"废话;敷衍的话;兜圈子的话","en":"If you describe what someone has said as flannel, you disapprove because they have said a lot but they have avoided telling you what you wanted to know.","ex":{"en":"No amount of flannel could disguise that this was, at best, a minimalist solution.","cn":"说多少废话都无法掩饰这最多只是一个极简主义的解决方案。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"soft cloth, usually made of cotton or wool, used for making clothes 〔","cn":"用作衣料的〕法兰绒"},{"en":"a piece of cloth you use to wash yourself 〔","cn":"洗澡用的〕毛巾"},{"en":"something that someone says that has no real meaning or does not tell you what you want to know","cn":"废话﹔兜圈子的话"}]},"collocations":{"phrases":["ADJ. damp, wet | cold | face","VERB + FLANNEL use Use a damp flannel to clean the skin.","PREP. with a ~ She wiped his eyes and nose with a wet face flannel."]},"media":{"uk":"media/ldoce/hwd/bre/c/flannel_n0205.mp3","us":"media/ldoce/hwd/ame/0/flannel.mp3"},"examples":[{"en":"a grey flannel suit","cn":"一套灰法兰绒西服"},{"en":"a flannel shirt","cn":"法兰绒衬衣"}],"oxford":{"phon":"ˈflænl","pos":"noun","senses":[{"en":"a type of soft light cloth, containing cotton or wool, used for making clothes","cn":"法兰绒","g":"[uncountable]","ex":{"en":"a flannel shirt","cn":"法兰绒衬衣"}},{"en":"a small piece of cloth used for washing yourself","cn":"（洗擦身体用的）小毛巾","g":"[countable]","lab":"both British English","ex":{"en":"a face flannel","cn":"洗脸毛巾"}},{"en":"trousers made of flannel","cn":"法兰绒裤","g":"[plural]","ex":{"en":"cricket flannels","cn":"板球法兰绒"}},{"en":"words that do not have much meaning and that avoid telling somebody what they want to know","cn":"兜圈子的话语；应付性言语","g":"[uncountable]","lab":"British English, informal，，","ex":{"en":"OK, cut the flannel and tell me what you really want!","cn":"好吧，剪下法兰绒，告诉我你真正想要什么！"}}]}},"flushed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"兴奋的;激动的","en":"If you say that someone is flushed with success or pride you mean that they are very excited by their success or pride.","ex":{"en":"Grace was flushed with the success of the venture","cn":"格雷斯为冒险成功而感到兴奋。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"red in the face","cn":"脸红的"},{"en":"excited because you have achieved something","cn":"因成功/激动/满意等而兴奋的"}]},"vocab":{"pos":"adj","senses":[{"en":"When you're flushed , your cheeks are pink. You probably look flushed after your morning jog around the block."}]},"collocations":{"phrases":["VERBS appear, be, feel, look | become","ADV. deeply, extremely, very | a bit, faintly, a little, quite, slightly | unnaturally","PREP. with Her face was flushed with embarrassment."]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeflushed.mp3","us":"media/ldoce/hwd/ame/4/flushed.mp3"},"examples":[{"en":"( figurative ) He was flushed with success (= very excited and pleased) after his first novel was published.","cn":"他的第一部小说发表以后，他志得意满。"},{"en":"Her face was flushed with anger.","cn":"她的脸气红了。"}],"oxford":{"phon":"flʌʃt","pos":"adjective","senses":[{"en":"red; with a red face","cn":"脸红的","lab":"figurative","ex":{"en":"flushed cheeks","cn":"发红的双颊"}}]},"base":"flush"},"flurry":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(活动或兴奋心情的)一阵","en":"A flurry of something such as activity or excitement is a short intense period of it.","ex":{"en":"...a flurry of diplomatic activity aimed at ending the war.","cn":"旨在结束战争的一系列外交活动"}},{"pos":"N-COUNT 可数名词","cn":"(雪等的)一阵","en":"A flurry of something such as snow is a small amount of it that suddenly appears for a short time and moves in a quick, swirling way."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a time when there is suddenly a lot of activity and people are very busy","cn":"一阵忙乱"},{"en":"a small amount of snow or rain that is blown by the wind 〔","cn":"雪或雨的〕微飘﹐一阵"}]},"vocab":{"pos":"n v","senses":[{"en":"A light blowing swirl of snow that's just barely falling is a flurry . There might be a brief flurry or two at the beginning of the winter, with no real heavy snow until January."}]},"collocations":{"phrases":["ADJ. snow","PHRASES a flurry of rain/snow 2 short sudden burst of sth","ADJ. brief, sudden There was a sudden flurry of interest in the book.","PREP. ~ of","PHRASES a flurry of activity/excitement"]},"media":{"uk":"media/ldoce/hwd/bre/f/flurry0205.mp3","us":"media/ldoce/hwd/ame/9/flurry1.mp3"},"examples":[{"en":"The ladies departed in a flurry of silks and satins.","cn":"女士们在一片绸缎窸窣声中离去。"},{"en":"Her arrival caused a flurry of excitement.","cn":"她的到来引起了一阵哄动。"}],"oxford":{"phon":"ˈflʌri","pos":"noun","senses":[{"en":"an occasion when there is a lot of activity, interest, excitement, etc. within a short period of time","cn":"一阵忙乱（或激动、兴奋等）","g":"[usually singular]","ex":{"en":"a sudden flurry of activity","cn":"突然的频繁活动"}},{"en":"a small amount of snow, rain, etc. that falls for a short time and then stops","cn":"小阵雪（或雨等）","ex":{"en":"snow flurries","cn":"小雪阵阵"}},{"en":"a sudden short movement of paper or cloth, especially clothes","cn":"（纸张、织物，尤指衣服）窸窣","ex":{"en":"The ladies departed in a flurry of silks and satins.","cn":"女士们在一片绸缎窸窣声中离去。"}}]}},"flap":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)飘动;摆动;抖搂","en":"If something such as a piece of cloth or paper flaps or if you flap it, it moves quickly up and down or from side to side.","ex":{"en":"Grey sheets flapped on the clothes line","cn":"灰色的床单在晾衣绳上飘来摆去的。"}},{"pos":"V-ERG 及物/不及物动词","cn":"振(翅);挥(翅);(翅膀)拍打，抖动","en":"If a bird or insect flaps its wings or if its wings flap, the wings move quickly up and down.","ex":{"en":"The bird flapped its wings furiously","cn":"鸟儿使劲地扑打着翅膀。"}},{"pos":"VERB 动词","cn":"挥动，舞动(手臂)","en":"If you flap your arms, you move them quickly up and down as if they were the wings of a bird.","ex":{"en":"...a kid running and flapping her arms.","cn":"边跑边挥舞着手臂的小孩子"}},{"pos":"N-COUNT 可数名词","cn":"(布、皮等)扁平下垂物,垂下的部分","en":"A flap of cloth or skin, for example, is a flat piece of it that can move freely up and down or from side to side because it is held or attached by only one edge.","ex":{"en":"He drew back the tent flap and strode out into the blizzard.","cn":"他拉开帐篷的门帘，大步走进暴风雪中。"}},{"pos":"N-COUNT 可数名词","cn":"(飞机的)襟翼，副翼，阻力板","en":"A flap on the wing of an aircraft is an area along the edge of the wing that can be raised or lowered to control the movement of the aircraft.","ex":{"en":"...the sudden slowing as the flaps were lowered.","cn":"襟翼放下时的突然减速"}},{"pos":"N-COUNT 可数名词","cn":"(鸟翼、布条、纸片的)拍打声，拍动，拍打","en":"A flap is a sudden noise or movement made by a bird's wing or by a piece of paper or cloth when it flaps.","ex":{"en":"Nothing to be heard but the soft flap of a silk banner.","cn":"万籁俱寂，只有一面绸制旗子轻轻飘动的响声。"}},{"pos":"N-SING 单数名词","cn":"激动;焦虑;惊慌","en":"Someone who is in a flap is in a state of great excitement, worry, or panic.","ex":{"en":"Why did people get in a flap over nuclear energy?","cn":"为什么人们对核能惶恐不安呢？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin flat piece of cloth, paper, skin etc that is fixed by one edge to a surface, which you can lift up easily 〔","cn":"布﹑纸﹑皮等做的〕片状垂悬物"},{"en":"the noisy movement of something such as cloth in the air 〔","cn":"布等在空中的〕拍打﹐拍动"},{"en":"a situation in which people feel very excited or worried about something","cn":"激动﹔慌乱﹐焦急"}]},"vocab":{"pos":"1 v n 2 n v 3 v","senses":[{"en":"You're probably familiar with the verb to \"flap,\" which is what birds do with their wings. But as a noun, a flap is a fuss, an argument, or a gossipy feud."}]},"collocations":{"phrases":["ADV. gently | wildly The sails flapped wildly in the stiff breeze. | about, around"]},"media":{"uk":"media/ldoce/hwd/bre/2/flap_las3_br.mp3","us":"media/ldoce/hwd/ame/6/flap1.mp3"},"examples":[{"en":"She walked up and down, flapping her arms to keep warm.","cn":"她来回走动，挥动着双臂使身体暖和起来。"},{"en":"There's no need to flap — I've got everything under control.","cn":"不必担心，一切都已在我控制之中。"}],"oxford":{"phon":"flæp","pos":"noun","senses":[{"en":"a flat piece of paper, cloth, metal, etc. that is attached to something along one side and that hangs down or covers an opening","cn":"（附于某物的）片状下垂物，封盖，口盖，袋盖","g":"[countable]","sc":"flat piece of paper, etc.","ex":{"en":"the flap of an envelope","cn":"信封的封盖"}},{"en":"a quick often noisy movement of something up and down or from side to side","cn":"（上下或左右）拍打，振（翅），拍击","g":"[countable, usually singular]","sc":"movement","ex":{"en":"With a flap of its wings, the bird was gone.","cn":"鸟拍打着翅膀飞走了。"}},{"en":"a state of worry and excitement","cn":"焦虑不安；紧张兴奋","g":"[singular]","lab":"informal, especially British English，，","sc":"worry/excitement","ex":{"en":"She gets in a flap over the slightest thing.","cn":"极小的事也能令她不安。"}},{"en":"public anger or criticism caused by something a public figure has said or done","cn":"群众愤怒；公众批评","g":"[singular]","lab":"North American English","sc":"public anger/criticism","ex":{"en":"the flap about the President’s business affairs","cn":"公众对总统公务的批评"}},{"en":"a part of the wing of an aircraft, at the back of the wing, that can be moved up or down to control movement in either direction","cn":"（飞机的）襟翼","g":"[countable]","lab":"specialist","sc":"part of aircraft","ex":{"en":"The wing flaps were not extended at the time of the accident.","cn":"事故发生时襟翼未展开。"}},{"en":"a speech sound that is produced by striking the tongue quickly and lightly against the part of the mouth behind the upper front teeth","cn":"皮瓣：一种语音，是通过轻轻地将舌头撞击上前牙后面的口腔部分而产生的","g":"[countable]","lab":"phonetics","sc":"phonetics"},{"en":"if a bird flaps its wings, or if its wings flap, they move quickly up and down","cn":"振（翅）","g":"[transitive, intransitive]","sc":"move quickly","ex":{"en":"The bird flapped its wings and flew away.","cn":"鸟振翅飞去。"},"pos":"verb"},{"en":"to move or to make something move up and down or from side to side, often making a noise","cn":"（使上下或左右）拍打，拍击，摆动","g":"[intransitive, transitive]","sc":"move quickly","ex":{"en":"The sails flapped in the breeze.","cn":"风帆在微风中摆动。"},"pos":"verb"},{"en":"to behave in an anxious or excited way","cn":"忧虑；激动","g":"[intransitive]","lab":"British English, informal，，","sc":"be worried/excited","ex":{"en":"There's no need to flap—I've got everything under control.","cn":"不必担心，一切都已在我控制之中。"},"pos":"verb"},{"en":"to produce a flap","cn":"襟翼：产生襟翼","g":"[transitive]","lab":"phonetics","sc":"phonetics","pos":"verb"}]}},"float":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)漂浮;(使)浮动","en":"If something or someone is floating in a liquid, they are in the liquid, on or just below the surface, and are being supported by it. You can also float something on a liquid.","ex":{"en":"They noticed fifty and twenty dollar bills floating in the water.","cn":"他们发现水中漂浮着50和20美元的纸币。"}},{"pos":"VERB 动词","cn":"漂;浮","en":"Something that floats lies on or just below the surface of a liquid when it is put in it and does not sink.","ex":{"en":"Empty things float.","cn":"空的物体会在水中浮起。"}},{"pos":"N-COUNT 可数名词","cn":"浮体;浮板;救生圈","en":"A float is a light object that is used to help someone or something float."},{"pos":"N-COUNT 可数名词","cn":"(钓鱼用的)鱼漂浮子","en":"A float is a small object attached to a fishing line which floats on the water and moves when a fish has been caught."},{"pos":"VERB 动词","cn":"(在空中)飘荡，飘浮","en":"Something that floats in or through the air hangs in it or moves slowly and gently through it.","ex":{"en":"The white cloud of smoke floated away.","cn":"白色的烟雾飘远了。"}},{"pos":"VERB 动词","cn":"(声音或气味)飘到，传到","en":"If a sound or smell floats to a place quite far away, it can be heard or smelled there.","ex":{"en":"Sublime music floats on a scented summer breeze to the spot where you lie on the lush grass","cn":"你躺在绿草如茵的草地上，涤荡心灵的乐声随着清香的夏日微风飘到你的身边。"}},{"pos":"VERB 动词","cn":"优雅地走动;轻盈地走动","en":"If you float somewhere, you walk there very lightly and gracefully.","ex":{"en":"Caroline floated up the aisle on her father's arm.","cn":"卡罗琳挽着父亲的手臂从过道上优雅地走过。"}},{"pos":"VERB 动词","cn":"提出(计划、方案或想法)","en":"If you float a project, plan, or idea, you suggest it for others to think about.","ex":{"en":"The French had floated the idea of placing the diplomatic work in the hands of the UN.","cn":"法国提出将外交工作交由联合国处理的想法。"}},{"pos":"VERB 动词","cn":"使(公司)发行股票;使上市","en":"If a company director floats their company, they start to sell shares in it to the public.","ex":{"en":"He floated his firm on the stock market","cn":"他让自己的公司上市了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(货币)自由浮动","en":"If a government floats its country's currency or allows it to float, it allows the currency's value to change freely in relation to other currencies.","ex":{"en":"A decision by the Finns to float their currency sent a shudder through the foreign exchanges","cn":"芬兰允许其货币自由浮动的决定在外汇市场上引起了震动。"}},{"pos":"N-COUNT 可数名词","cn":"(节日游行时的)彩车，花车","en":"A float is a truck on which displays and people in special costumes are carried in a festival procession."},{"pos":"N-SING 单数名词","cn":"(商店的)备用零钱","en":"A float is a small amount of coins and notes of low value that someone has before they start selling things so that they are able to give customers change if necessary."},{"pos":"PHRASAL VERB 短语动词","cn":"传开;流传","en":"A rumour or idea that is floating around is often heard or talked about.","ex":{"en":"There are still some unfounded fears floating around out there about cancer being contagious.","cn":"社会上还是有一些毫无根据的关于癌症会传染的恐惧。"}},{"pos":"","cn":"","en":"相关词组：float around"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be supported on the surface of water by the water itself","cn":""},{"en":"to stay on the surface of water without sinking","cn":""},{"en":"to formally suggest that something should be done, especially at a meeting","cn":""}]},"vocab":{"pos":"1 v n 2 n v 3 v 4 v ","senses":[{"en":"Float is what you do when you're lying on the water. Hopefully you know how to swim, so you can float suspended on the surface of the water, rather than sinking straight to the bottom."}]},"collocations":{"phrases":["ADV. gently | downstream, downwards | upwards In the dream my feet leave the ground and I start to float upwards. | about, around, away, off","VERB + FLOAT seem to Her voice seemed to float on the water as gently as a slight mist.","PREP. across A few small clouds floated across the sky. | down chunks of ice floating down the river | in pieces of wood floating in the wat","ADV. freely The government decided to allow the peso to float freely.","VERB + FLOAT allow sth to"]},"media":{"img":["media/ldoce/img/float.jpg"],"uk":"media/ldoce/hwd/bre/c/brelasdefloat.mp3","us":"media/ldoce/hwd/ame/e/float1.mp3"},"examples":[{"en":"Shares were floated at 585p.","cn":"股票最初上市价为 5 英镑 85 便士。"},{"en":"( figurative ) People seem to float in and out of my life.","cn":"不同的人在我的生命中出现和消失。"}],"oxford":{"phon":"fləʊt","pos":"verb","senses":[{"en":"to move slowly on water or in the air","cn":"浮动；漂流；飘动；飘移","g":"[intransitive]","lab":"figurative","sc":"on water/in air","ex":{"en":"A group of swans floated by.","cn":"一群天鹅缓缓游过。"}},{"en":"to stay on or near the surface of a liquid and not sink","cn":"浮；漂浮","g":"[intransitive]","sc":"on water/in air","ex":{"en":"Wood floats.","cn":"木头能浮起来。"}},{"en":"to make something move on or near the surface of a liquid","cn":"使浮动；使漂流","g":"[transitive]","sc":"on water/in air","ex":{"en":"There wasn't enough water to float the ship.","cn":"水不够深，船浮动不起来。"}},{"en":"to walk or move in a smooth and easy way","cn":"轻盈走动；飘然移动","g":"[intransitive]","lab":"literary","sc":"walk lightly","ex":{"en":"She floated down the steps to greet us.","cn":"她轻盈地下楼来迎接我们。"}},{"en":"to suggest an idea or a plan for other people to consider","cn":"提出，提请考虑（想法或计划）","g":"[transitive]","sc":"suggest idea","ex":{"en":"They floated the idea of increased taxes on alcohol.","cn":"他们建议提高酒税。"}},{"en":"to sell shares in a company or business to the public for the first time","cn":"（公司或企业）首次公开发行（股票），使上市","g":"[transitive]","lab":"business","sc":"business/economics","ex":{"en":"The company was floated on the stock market in 2014.","cn":"这家公司于 2014 年上市。"}},{"en":"if a government floats its country’s money or allows it to float, it allows its value to change freely according to the value of the money of other countries","cn":"（使货币汇率）自由浮动","g":"[transitive, intransitive]","lab":"economics","sc":"business/economics","ex":{"en":"The government decided to allow the peso to float freely.","cn":"政府决定让比索自由浮动。"}},{"en":"a large vehicle on which people dressed in special costumes are carried in a festival","cn":"彩车","sc":"vehicle","ex":{"en":"a carnival float","cn":"狂欢节彩车"},"pos":"noun"},{"en":"a small light object attached to a fishing line that stays on the surface of the water and moves when a fish has been caught","cn":"浮子；鱼漂","sc":"in fishing","ex":{"en":"float fishing","cn":"浮钓"},"pos":"noun"},{"en":"a light object that floats in the water and is held by a person who is learning to swim","cn":"（学游泳用的）浮板","sc":"for swimming","pos":"noun"},{"en":"a drink with ice cream floating in it","cn":"加冰激凌的饮料","lab":"North American English","sc":"drink","ex":{"en":"a Coke float","cn":"一杯加冰激凌的可口可乐"},"pos":"noun"},{"en":"a sum of money consisting of coins and notes of low value that is given to somebody before they start selling things so that they can give customers change","cn":"（商店的）备用零钱","lab":"especially British English","sc":"money","pos":"noun"},{"en":"the process of selling shares in a company to the public for the first time in order to raise money","cn":"（公司）首次公开发行股票","g":"[countable, uncountable]","sc":"business","pos":"noun"}]}},"fluid":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"液体;流质","en":"A fluid is a liquid.","ex":{"en":"The blood vessels may leak fluid, which distorts vision","cn":"血管可能会渗漏，造成视力模糊。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(动作、线条或设计)流畅优美的，优雅自然的","en":"Fluid movements or lines or designs are smooth and graceful.","ex":{"en":"The forehand stroke should be fluid and well balanced.","cn":"正手击球应该保证动作流畅和平稳。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不稳定的;不确定的","en":"A situation that is fluid is unstable and is likely to change often.","ex":{"en":"The situation is extremely fluid and it can be changing from day to day.","cn":"情况极不稳定，每天都有可能变化。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance, such as water or milk, that is not a solid and not a gas","cn":""},{"en":"a liquid - used especially in technical contexts","cn":""},{"en":"a liquid","cn":"流体﹐液（体）"}]},"vocab":{"pos":"1 n adj 2 adj 3 adj","senses":[{"en":"Something that is unstable or subject to change can be described as fluid . The fluid political situation in a particular country makes it unsafe to travel there, with the constant possibility of a violent uprising."}]},"collocations":{"phrases":["ADJ. excess | amniotic, bodily/body, intravenous | brake, cleaning","VERB + FLUID drink Change your diet and drink plenty of fluids. | lose | replace replacing vital body fluids and salts that are lost when yo"]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdefluid.mp3","us":"media/ldoce/hwd/ame/a/l3fluid.mp3"},"examples":[{"en":"a loose, fluid style of dancing","cn":"灵活流畅优美的跳舞风格"},{"en":"The doctor told him to drink plenty of fluids.","cn":"医生要他多喝流质。"}],"oxford":{"phon":"ˈfluːɪd","pos":"noun","senses":[{"en":"a liquid; a substance that can flow","cn":"液体；流体；液","ex":{"en":"body fluids (= for example, blood)","cn":"体液（如血液）"}},{"en":"smooth and beautiful","cn":"流畅优美的","lab":"formal","ex":{"en":"a loose, fluid style of dancing","cn":"灵活流畅的舞蹈风格"},"pos":"adjective"},{"en":"likely to change; not fixed","cn":"易变的；不稳定的","lab":"formal","ex":{"en":"The fluid political situation made investment impossible.","cn":"政治局势不稳定，因而未能吸引投资。"},"pos":"adjective"},{"en":"that can flow freely, as gases and liquids do","cn":"流动的；流体的","lab":"specialist","ex":{"en":"a fluid consistency","cn":"流体黏稠度"},"pos":"adjective"}]}},"flutter":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"颤动;飘动;挥动","en":"If something thin or light flutters, or if you flutter it, it moves up and down or from side to side with a lot of quick, light movements.","ex":{"en":"Her chiffon skirt was fluttering in the night breeze.","cn":"她的雪纺裙在晚风中飘动着。"}},{"pos":"VERB 动词","cn":"(小鸟)振翅飞翔;(纸片)飘飞，翩翩飞舞","en":"If something light such as a small bird or a piece of paper flutters somewhere, it moves through the air with small quick movements.","ex":{"en":"The paper fluttered to the floor","cn":"纸飘落到地板上。"}},{"pos":"N-COUNT 可数名词","cn":"小赌注","en":"If you have a flutter, you have a small bet on something such as a horse race.","ex":{"en":"I had a flutter on five horses.","cn":"我在5匹马身上下了小赌注。"}},{"pos":"VERB 动词","cn":"匆忙急赶;奔走","en":"If you say that someone flutters somewhere, you mean that they walk there with quick, light movements, often in a silly way or in a way which suggests that they are nervous.","ex":{"en":"She'd been fluttering about in the kitchen.","cn":"她一直在厨房里忙前忙后。"}},{"pos":"VERB 动词","cn":"(心)扑通扑通地跳，怦怦直跳","en":"If your heart or stomach flutters, you experience a strong feeling of excitement or anxiety.","ex":{"en":"The look in his eyes made my heart flutter.","cn":"他的眼神让我心里扑通扑通直跳。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a bird or insect flutters, or if it flutters its wings, it flies by moving its wings lightly up and down","cn":"振（翼）﹐拍打（翅膀）"},{"en":"to make small gentle movements in the air 〔","cn":"在空中〕飘扬﹐飘动"},{"en":"if your heart or your stomach flutters, you feel very excited or nervous 〔","cn":"心脏或胃因激动或紧张而〕悸动﹐颤抖"}]},"vocab":{"pos":"1 v n 2 n","senses":[{"en":"Flutter means to move back and forth rapidly. Flags flutter in the wind. Leaves flutter to the ground. Flutter also exists as a noun—you might feel a flutter in your heart when you're excited."}]},"collocations":{"phrases":["ADJ. little","VERB + FLUTTER give His heart gave a little flutter as the ladder slipped a couple of inches. 2 state of nervous excitement","VERB + FLUTTER be in, feel She felt a flutter of excitement. | get in | cause","PREP. in a ~ They arrived in a flutter. | ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/d/flutter_v0205.mp3","us":"media/ldoce/hwd/ame/1/flutter1.mp3"},"examples":[{"en":"( figurative ) The sound of his voice in the hall made her heart flutter.","cn":"他在大厅中讲话的声音使她的心怦怦直跳。"},{"en":"Her eyelids fluttered but did not open.","cn":"她的眼皮动了一下，但没有睁开眼。"}],"oxford":{"phon":"ˈflʌtə(r)","pos":"verb","senses":[{"en":"to move lightly and quickly; to make something move in this way","cn":"（使）飘动，挥动，颤动","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"Flags fluttered in the breeze.","cn":"旗帜在微风中飘扬。"}},{"en":"when a bird or an insect flutters its wings, or its wings flutter, the wings move lightly and quickly up and down","cn":"（鸟或昆虫）拍（翅），振（翅），鼓（翼）","g":"[intransitive, transitive]"},{"en":"to fly somewhere moving the wings quickly and lightly","cn":"飞来飞去；翩翩飞舞","g":"[intransitive]","ex":{"en":"The butterfly fluttered from flower to flower.","cn":"蝴蝶在花丛中飞来飞去。"}},{"en":"to beat very quickly and not regularly","cn":"怦怦乱跳；扑腾","g":"[intransitive]","lab":"figurative","ex":{"en":"I could feel a fluttering pulse.","cn":"我感到脉搏跳动。"}},{"en":"a quick, light movement","cn":"振动；飘动；挥动；颤动","g":"[countable, usually singular]","lab":"figurative","ex":{"en":"the flutter of wings","cn":"翅膀的拍动"},"pos":"noun"},{"en":"a small bet","cn":"小赌注","g":"[countable, usually singular]","lab":"British English, informal，，","ex":{"en":"to have a flutter on the horses","cn":"赛马中下小赌注"},"pos":"noun"},{"en":"a state of nervous or confused excitement","cn":"紧张兴奋；慌乱","g":"[singular]","ex":{"en":"Her sudden arrival caused quite a flutter.","cn":"她的突然到来引起一片慌乱。"},"pos":"noun"},{"en":"a very fast heartbeat, caused when somebody is nervous or excited","cn":"（心脏的）怦怦乱跳，扑腾","g":"[countable]","ex":{"en":"Her heart gave a flutter when she saw him.","cn":"她见到他时心怦怦乱跳。"},"pos":"noun"},{"en":"a medical condition in which you have an unsteady heartbeat","cn":"扑动；快速的颤动（或搏动）","g":"[uncountable, countable]","lab":"medical","pos":"noun"},{"en":"rapid changes in the pitch or volume of recorded sound","cn":"（重放录音的）颤振","g":"[uncountable]","lab":"specialist","pos":"noun"}]}}});
